import { GoogleGenAI, Modality, Type } from "@google/genai";
import { FeedbackResponse } from "../types";

const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

// Helper: Convert Blob to Base64
export const blobToBase64 = (blob: Blob): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = reader.result as string;
      // Remove data url prefix (e.g. "data:audio/wav;base64,")
      const base64Content = base64String.split(',')[1];
      resolve(base64Content);
    };
    reader.onerror = reject;
    reader.readAsDataURL(blob);
  });
};

// 1. Generate Speech (TTS)
export const generateSpeech = async (text: string): Promise<string | null> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: 'Kore' }, // 'Kore' is usually clear
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    return base64Audio || null;
  } catch (error) {
    console.error("TTS Error:", error);
    return null;
  }
};

// 2. Evaluate Pinyin Writing
export const checkPinyinWithGemini = async (targetWord: string, targetPinyin: string, userInput: string): Promise<FeedbackResponse> => {
  try {
    const prompt = `
      You are a friendly Chinese teacher for an 8-year-old foreign student.
      The target word is "${targetWord}" (${targetPinyin}).
      The student wrote: "${userInput}".
      Check if the pinyin is correct (ignore minor spacing, but tone marks or numbers for tones are important. e.g. 'ma1' or 'mā' are acceptable).

      Respond in JSON format:
      {
        "isCorrect": boolean,
        "message": "Simple explanation in English for an 8 year old."
      }
      If correct, message should be encouraging (e.g. "Great job!").
      If wrong, explain gently (e.g. "Oops! You missed the first tone." or "Close, but it's 'zuó', not 'zu'.").
    `;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            isCorrect: { type: Type.BOOLEAN },
            message: { type: Type.STRING },
          },
          required: ["isCorrect", "message"]
        }
      }
    });

    const result = JSON.parse(response.text || '{}');
    return result;
  } catch (error) {
    console.error("Pinyin Check Error:", error);
    return { isCorrect: false, message: "Teacher is having trouble connecting. Try again!" };
  }
};

// 3. Evaluate Pronunciation (Audio)
export const evaluateAudioWithGemini = async (targetPinyin: string, audioBlob: Blob): Promise<FeedbackResponse> => {
  try {
    const base64Audio = await blobToBase64(audioBlob);

    const prompt = `
      You are a kind Chinese teacher for kids.
      The student is trying to say the pinyin/word: "${targetPinyin}".
      Listen to the audio. Is the pronunciation acceptable for a beginner 8-year-old?

      Respond in JSON format:
      {
        "isCorrect": boolean,
        "message": "Simple feedback in English."
      }
      If correct, say something like "Nice pronunciation!".
      If wrong, point out the specific error gently (e.g. "Make your voice go up for the second tone!").
    `;

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-native-audio-preview-12-2025",
      contents: {
        parts: [
          { inlineData: { mimeType: "audio/wav", data: base64Audio } }, // Assuming webm/wav from browser
          { text: prompt }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            isCorrect: { type: Type.BOOLEAN },
            message: { type: Type.STRING },
          },
          required: ["isCorrect", "message"]
        }
      }
    });

    const result = JSON.parse(response.text || '{}');
    return result;
  } catch (error) {
    console.error("Audio Eval Error:", error);
    // Fallback if audio model fails (e.g. mime type issues)
    return { isCorrect: false, message: "I couldn't hear you clearly. Can you try again?" };
  }
};

