import React, { useEffect, useState } from 'react';
import { generateSpeech } from '../services/geminiService';

interface AudioPlayerProps {
  text: string;
  autoPlay?: boolean;
  label?: string;
}

const AudioPlayer: React.FC<AudioPlayerProps> = ({ text, autoPlay = false, label = "Listen" }) => {
  const [audioSrc, setAudioSrc] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const handlePlay = async () => {
    if (audioSrc) {
      new Audio(audioSrc).play();
      return;
    }

    setLoading(true);
    const base64 = await generateSpeech(text);
    if (base64) {
      const src = `data:audio/mp3;base64,${base64}`;
      setAudioSrc(src);
      new Audio(src).play();
    }
    setLoading(false);
  };

  useEffect(() => {
    if (autoPlay) {
      handlePlay();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [text]);

  return (
    <button
      onClick={handlePlay}
      disabled={loading}
      className={`
        flex items-center gap-2 px-6 py-3 rounded-full font-bold text-lg
        ${loading ? 'bg-gray-300' : 'bg-yellow-400 hover:bg-yellow-500 text-yellow-900 border-b-4 border-yellow-600 btn-press'}
      `}
    >
      {loading ? (
        <span className="animate-spin">⌛</span>
      ) : (
        <span>🔊</span>
      )}
      {label}
    </button>
  );
};

export default AudioPlayer;

import React, { useState } from 'react';
import { VocabularyItem, SubmissionRecord } from '../types';
import AudioPlayer from './AudioPlayer';
import { checkPinyinWithGemini } from '../services/geminiService';
import { SOUNDS, PLACEHOLDER_IMAGES } from '../constants';

interface Props {
  data: VocabularyItem[];
  onComplete: (records: SubmissionRecord[]) => void;
}

const PinyinPractice: React.FC<Props> = ({ data, onComplete }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [input, setInput] = useState('');
  const [feedback, setFeedback] = useState<string | null>(null);
  const [isCorrect, setIsCorrect] = useState(false);
  const [loading, setLoading] = useState(false);
  const [records, setRecords] = useState<SubmissionRecord[]>([]);

  const currentItem = data[currentIndex];

  const handleSubmit = async () => {
    if (!input.trim()) return;
    setLoading(true);
    setFeedback(null);

    const result = await checkPinyinWithGemini(currentItem.chinese, currentItem.pinyin, input);

    if (result.isCorrect) {
      new Audio(SOUNDS.CORRECT).play();
      setIsCorrect(true);
      setFeedback(result.message);

      // Save record
      setRecords(prev => [...prev, {
        type: 'writing',
        itemId: currentItem.id,
        input: input,
        score: 1,
        feedback: result.message
      }]);

    } else {
      new Audio(SOUNDS.WRONG).play();
      setIsCorrect(false);
      setFeedback(result.message);
    }
    setLoading(false);
  };

  const handleNext = () => {
    setInput('');
    setFeedback(null);
    setIsCorrect(false);

    if (currentIndex < data.length - 1) {
      setCurrentIndex(prev => prev + 1);
    } else {
      onComplete(records);
    }
  };

  return (
    <div className="flex flex-col items-center justify-center h-full">
      <h2 className="text-3xl font-bold text-gray-700 mb-6">👂 Listen & Write Pinyin</h2>

      <div className="bg-blue-50 p-6 rounded-3xl border-4 border-blue-200 mb-8 flex flex-col items-center gap-4 w-full max-w-md">
        <img 
          src={PLACEHOLDER_IMAGES[currentItem.imageKeyword]} 
          alt={currentItem.english}
          className="w-48 h-48 object-cover rounded-2xl border-2 border-white shadow-md mb-2"
        />
        <div className="text-6xl font-bold text-gray-800 mb-2">{currentItem.chinese}</div>
        <div className="text-xl text-gray-500 font-medium bg-white px-4 py-1 rounded-full shadow-sm">{currentItem.english}</div>

        <AudioPlayer text={currentItem.chinese} autoPlay label="Play Sound" />
      </div>

      <div className="w-full max-w-md space-y-4">
        <input
          type="text"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          placeholder="Type pinyin (e.g. zuótiān)"
          className="w-full text-center text-3xl p-4 rounded-2xl border-4 border-gray-300 focus:border-blue-400 focus:outline-none"
          disabled={isCorrect || loading}
        />

        {!isCorrect && (
          <button
            onClick={handleSubmit}
            disabled={loading || !input}
            className={`w-full py-4 rounded-2xl font-bold text-xl text-white transition-all
              ${loading || !input ? 'bg-gray-300' : 'bg-green-400 hover:bg-green-500 border-b-4 border-green-600 btn-press'}
            `}
          >
            {loading ? 'Teacher is checking...' : 'Check Answer ✨'}
          </button>
        )}

        {feedback && (
          <div className={`p-4 rounded-2xl text-center font-medium text-lg border-2 animate-bounce
            ${isCorrect ? 'bg-green-100 border-green-300 text-green-700' : 'bg-red-100 border-red-300 text-red-700'}
          `}>
            {isCorrect ? '🎉 ' : '👩‍🏫 '} {feedback}
          </div>
        )}

        {isCorrect && (
          <button
            onClick={handleNext}
            className="w-full py-4 rounded-2xl font-bold text-xl text-white bg-blue-400 hover:bg-blue-500 border-b-4 border-blue-600 btn-press"
          >
            Next Word ➡️
          </button>
        )}
      </div>

      <div className="mt-8 text-gray-400 font-bold">
        {currentIndex + 1} / {data.length}
      </div>
    </div>
  );
};

export default PinyinPractice;

import React, { useState, useRef } from 'react';
import { VocabularyItem, SubmissionRecord } from '../types';
import AudioPlayer from './AudioPlayer';
import { evaluateAudioWithGemini } from '../services/geminiService';
import { SOUNDS, PLACEHOLDER_IMAGES } from '../constants';

interface Props {
  data: VocabularyItem[];
  onComplete: (records: SubmissionRecord[]) => void;
}

const SpeakingPractice: React.FC<Props> = ({ data, onComplete }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isRecording, setIsRecording] = useState(false);
  const [feedback, setFeedback] = useState<string | null>(null);
  const [isCorrect, setIsCorrect] = useState(false);
  const [loading, setLoading] = useState(false);
  const [records, setRecords] = useState<SubmissionRecord[]>([]);

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);

  const currentItem = data[currentIndex];

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      chunksRef.current = [];

      mediaRecorder.ondataavailable = (e) => {
        if (e.data.size > 0) chunksRef.current.push(e.data);
      };

      mediaRecorder.onstop = async () => {
        const blob = new Blob(chunksRef.current, { type: 'audio/webm' }); // Browsers usually record to webm
        // To help Gemini, we might convert to WAV, but recent Gemini updates handle various audio formats better. 
        // We pass the raw blob to the service which converts to base64.
        await handleAudioSubmit(blob);
      };

      mediaRecorder.start();
      setIsRecording(true);
      setFeedback(null);
    } catch (err) {
      console.error("Mic error", err);
      alert("Please allow microphone access!");
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      // Stop all tracks
      mediaRecorderRef.current.stream.getTracks().forEach(track => track.stop());
    }
  };

  const handleAudioSubmit = async (audioBlob: Blob) => {
    setLoading(true);
    const result = await evaluateAudioWithGemini(currentItem.pinyin, audioBlob);

    if (result.isCorrect) {
      new Audio(SOUNDS.CORRECT).play();
      setIsCorrect(true);
      setFeedback(result.message);

       setRecords(prev => [...prev, {
        type: 'speaking',
        itemId: currentItem.id,
        input: audioBlob,
        score: 1,
        feedback: result.message
      }]);
    } else {
      new Audio(SOUNDS.WRONG).play();
      setIsCorrect(false);
      setFeedback(result.message);
    }
    setLoading(false);
  };

  const handleNext = () => {
    setFeedback(null);
    setIsCorrect(false);
    if (currentIndex < data.length - 1) {
      setCurrentIndex(prev => prev + 1);
    } else {
      onComplete(records);
    }
  };

  return (
    <div className="flex flex-col items-center justify-center h-full">
      <h2 className="text-3xl font-bold text-gray-700 mb-6">🎤 Listen & Repeat</h2>

      <div className="bg-green-50 p-6 rounded-3xl border-4 border-green-200 mb-8 flex flex-col items-center gap-4 w-full max-w-md">
         <img 
          src={PLACEHOLDER_IMAGES[currentItem.imageKeyword]} 
          alt={currentItem.english}
          className="w-48 h-48 object-cover rounded-2xl border-2 border-white shadow-md mb-2"
        />
        <div className="text-6xl font-bold text-gray-800">{currentItem.chinese}</div>
        <div className="text-2xl text-blue-500 font-bold">{currentItem.pinyin}</div>
        <AudioPlayer text={currentItem.chinese} label="Hear Teacher" />
      </div>

      <div className="w-full max-w-md flex flex-col gap-4">
        {!isCorrect && (
           <button
             onMouseDown={startRecording}
             onMouseUp={stopRecording}
             onTouchStart={startRecording}
             onTouchEnd={stopRecording}
             disabled={loading}
             className={`
               w-full py-8 rounded-full font-bold text-2xl text-white shadow-lg transition-transform
               ${isRecording 
                 ? 'bg-red-500 scale-95 border-4 border-red-700' 
                 : 'bg-purple-500 hover:bg-purple-600 border-b-8 border-purple-700 btn-press'}
               ${loading ? 'opacity-50 cursor-not-allowed' : ''}
             `}
           >
             {loading ? 'Judging...' : isRecording ? '🛑 Release to Check' : '🎙️ Hold to Speak'}
           </button>
        )}

        {feedback && (
          <div className={`p-4 rounded-2xl text-center font-medium text-lg border-2
            ${isCorrect ? 'bg-green-100 border-green-300 text-green-700' : 'bg-red-100 border-red-300 text-red-700'}
          `}>
             {isCorrect ? '🎉 ' : '👩‍🏫 '} {feedback}
          </div>
        )}

        {isCorrect && (
          <button
            onClick={handleNext}
            className="w-full py-4 rounded-2xl font-bold text-xl text-white bg-blue-400 hover:bg-blue-500 border-b-4 border-blue-600 btn-press"
          >
            Next Word ➡️
          </button>
        )}
      </div>

      <div className="mt-8 text-gray-400 font-bold">
        {currentIndex + 1} / {data.length}
      </div>
    </div>
  );
};

export default SpeakingPractice;

import React, { useState } from 'react';
import { VocabularyItem } from '../types';
import { SOUNDS, PLACEHOLDER_IMAGES } from '../constants';

interface Props {
  data: VocabularyItem[];
  onComplete: () => void;
}

const Quiz: React.FC<Props> = ({ data, onComplete }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [showResult, setShowResult] = useState<'correct' | 'wrong' | null>(null);

  // Generate 3 options including the correct one
  const currentItem = data[currentIndex];

  // Create a randomized list of 3 options
  const [options] = useState(() => {
     // This state initializer runs only when component mounts or key changes. 
     // Ideally, we move this logic out or handle key-based resets.
     // For simplicity in this demo, we generate inside render logic if options are missing, but that causes re-render loops.
     // Better pattern: use effect or memo triggered by currentIndex.
     return [];
  });

  // Since we can't easily use complex hooks inside the change description without growing the file too large, 
  // let's do options generation on the fly in the render but stabilized.

  const generateOptions = (target: VocabularyItem, all: VocabularyItem[]) => {
    const others = all.filter(i => i.id !== target.id).sort(() => 0.5 - Math.random()).slice(0, 2);
    return [target, ...others].sort(() => 0.5 - Math.random());
  };

  const [currentOptions, setCurrentOptions] = useState<VocabularyItem[]>(generateOptions(currentItem, data));

  const handleSelect = (selectedId: string) => {
    if (showResult === 'correct') return; // prevent clicking after success

    if (selectedId === currentItem.id) {
      new Audio(SOUNDS.CORRECT).play();
      setShowResult('correct');
      setTimeout(() => {
        if (currentIndex < data.length - 1) {
            const nextIdx = currentIndex + 1;
            setCurrentIndex(nextIdx);
            setCurrentOptions(generateOptions(data[nextIdx], data));
            setShowResult(null);
        } else {
            onComplete();
        }
      }, 1500);
    } else {
      new Audio(SOUNDS.WRONG).play();
      setShowResult('wrong');
      // Visual feedback shakes or highlights
    }
  };

  return (
    <div className="flex flex-col items-center justify-center h-full">
      <h2 className="text-3xl font-bold text-gray-700 mb-8">🧩 Pick the Picture</h2>

      <div className="bg-white px-8 py-4 rounded-2xl shadow-sm border-2 border-gray-100 mb-8">
        <span className="text-5xl font-bold text-blue-600">{currentItem.pinyin}</span>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-3 gap-6 w-full">
        {currentOptions.map((opt) => (
          <button
            key={opt.id}
            onClick={() => handleSelect(opt.id)}
            className={`
              relative group overflow-hidden rounded-3xl border-4 transition-all
