import { SubmissionRecord, SavedSubmissionRecord, SavedReport } from '../types';
import { blobToBase64 } from './geminiService';

const STORAGE_KEY_PREFIX = 'panda_report_';

/**
 * Converts active session submissions (with Blobs) to a JSON-safe format (Base64).
 */
export const createSavedReport = async (
  lessonId: number, 
  studentName: string, 
  submissions: SubmissionRecord[]
): Promise<SavedReport> => {

  const savedSubmissions: SavedSubmissionRecord[] = await Promise.all(
    submissions.map(async (sub) => {
      let inputData = '';

      if (sub.input instanceof Blob) {
        inputData = await blobToBase64(sub.input);
      } else {
        inputData = String(sub.input);
      }

      return {
        type: sub.type,
        itemId: sub.itemId,
        input: inputData, // Now guaranteed to be a string
        score: sub.score,
        feedback: sub.feedback
      };
    })
  );

  const report: SavedReport = {
    id: crypto.randomUUID(),
    lessonId,
    studentName,
    timestamp: Date.now(),
    submissions: savedSubmissions
  };

  return report;
};

/**
 * Saves the report to "Cloud" (LocalStorage for demo purposes).
 */
export const saveReportToCloud = (report: SavedReport): string => {
  try {
    const key = `${STORAGE_KEY_PREFIX}${report.id}`;
    localStorage.setItem(key, JSON.stringify(report));
    return report.id;
  } catch (e) {
    console.error("Failed to save report", e);
    throw new Error("Storage full or unavailable");
  }
};

/**
 * Retrieves a report by ID.
 */
export const getReportFromCloud = (reportId: string): SavedReport | null => {
  try {
    const key = `${STORAGE_KEY_PREFIX}${reportId}`;
    const data = localStorage.getItem(key);
    if (!data) return null;
    return JSON.parse(data) as SavedReport;
  } catch (e) {
    console.error("Failed to load report", e);
    return null;
  }
};

/**
 * Helper to reconstruct a Blob from Base64 (for playing audio in Teacher View).
 */
export const base64ToBlob = (base64: string, mimeType: string = 'audio/webm'): Blob => {
  const byteCharacters = atob(base64);
  const byteNumbers = new Array(byteCharacters.length);
  for (let i = 0; i < byteCharacters.length; i++) {
    byteNumbers[i] = byteCharacters.charCodeAt(i);
  }
  const byteArray = new Uint8Array(byteNumbers);
  return new Blob([byteArray], { type: mimeType });
};

