import React, { useState, useEffect, useMemo } from 'react';
import { VocabularyItem, SubmissionRecord } from '../types';
import AudioPlayer from './AudioPlayer';
import { speakText } from '../services/geminiService';
import { SOUNDS, PLACEHOLDER_IMAGES } from '../constants';

interface Props {
  data: VocabularyItem[];
  onComplete: (records: SubmissionRecord[]) => void;
}

// Map base vowels to their toned versions [flat, rising, dipping, falling, neutral]
const TONE_MAP: Record<string, string[]> = {
  'a': ['ā', 'á', 'ǎ', 'à', 'a'],
  'e': ['ē', 'é', 'ě', 'è', 'e'],
  'i': ['ī', 'í', 'ǐ', 'ì', 'i'],
  'o': ['ō', 'ó', 'ǒ', 'ò', 'o'],
  'u': ['ū', 'ú', 'ǔ', 'ù', 'u'],
  'ü': ['ǖ', 'ǘ', 'ǚ', 'ǜ', 'ü'],
};

// Helper to check if a char is a vowel (including toned versions)
const isVowel = (char: string) => {
  const base = getBaseChar(char);
  return ['a', 'e', 'i', 'o', 'u', 'ü'].includes(base);
};

// Helper to get base char (e.g., 'á' -> 'a')
const getBaseChar = (char: string): string => {
  for (const [base, variants] of Object.entries(TONE_MAP)) {
    if (variants.includes(char)) return base;
  }
  return char;
};

const PinyinPractice: React.FC<Props> = ({ data, onComplete }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [userInput, setUserInput] = useState<string[]>([]); // Array of chars for easier manipulation
  const [penaltyTime, setPenaltyTime] = useState(0); 
  const [records, setRecords] = useState<SubmissionRecord[]>([]);

  const currentItem = data[currentIndex];

  // Timer effect for penalty
  useEffect(() => {
    let timer: number;
    if (penaltyTime > 0) {
      timer = window.setInterval(() => {
        setPenaltyTime((prev) => prev - 1);
      }, 1000);
    } else if (penaltyTime === 0) {
        // Timer finished
    }
    return () => clearInterval(timer);
  }, [penaltyTime]);

  // Generate a pool of letters based on the target word + some distractors
  const letterPool = useMemo(() => {
    // Get unique base chars from the pinyin, ignoring spaces
    const targetChars = currentItem.pinyin.replace(/\s/g, '').split('').map(getBaseChar);
    const uniqueChars = Array.from(new Set(targetChars));

    // Add some common pinyin letters as distractors
    const commonDistractors = ['a', 'o', 'e', 'i', 'u', 'b', 'p', 'm', 'f', 'd', 't', 'n', 'l', 'g', 'k', 'h', 'j', 'q', 'x'];

    // Fill up to 12 letters if needed
    while (uniqueChars.length < 12) {
        const randomChar = commonDistractors[Math.floor(Math.random() * commonDistractors.length)];
        if (!uniqueChars.includes(randomChar)) {
            uniqueChars.push(randomChar);
        }
    }

    // Shuffle
    return uniqueChars.sort(() => 0.5 - Math.random());
  }, [currentItem]);

  // Reset input when word changes
  useEffect(() => {
    setUserInput([]);
    setPenaltyTime(0);
  }, [currentIndex]);

  const handleAddLetter = (char: string) => {
    if (penaltyTime > 0) return;
    setUserInput(prev => [...prev, char]);
  };

  const handleBackspace = () => {
    if (penaltyTime > 0) return;
    setUserInput(prev => prev.slice(0, -1));
  };

  const handleToneChange = (toneIndex: number) => {
    if (penaltyTime > 0 || userInput.length === 0) return;

    // Modify the LAST character if it's a vowel
    const lastChar = userInput[userInput.length - 1];
    const base = getBaseChar(lastChar);

    if (TONE_MAP[base]) {
        const newChar = TONE_MAP[base][toneIndex];
        const newInput = [...userInput];
        newInput[newInput.length - 1] = newChar;
        setUserInput(newInput);
    }
  };

  const checkAnswer = () => {
    const inputString = userInput.join('');
    // Remove spaces from target since we track input without spaces
    const targetString = currentItem.pinyin.replace(/\s/g, '');

    if (inputString === targetString) {
      // Correct!
      new Audio(SOUNDS.CORRECT).play();
      speakText("Excellent!", "en-US");

      const newRecord: SubmissionRecord = {
        type: 'writing',
        itemId: currentItem.id,
        input: inputString,
        score: 1,
        feedback: "Correct Pinyin Construction"
      };

      const updatedRecords = [...records, newRecord];
      setRecords(updatedRecords);

      // Delay slightly before next
      setTimeout(() => {
        if (currentIndex < data.length - 1) {
            setCurrentIndex(prev => prev + 1);
        } else {
            onComplete(updatedRecords);
        }
      }, 1500);

    } else {
      // Wrong!
      new Audio(SOUNDS.WRONG).play();
      speakText("Not quite. Look at the correct answer!", "en-US");
      setPenaltyTime(10); // Start 10s penalty
    }
  };

  const isPenaltyActive = penaltyTime > 0;

  return (
    <div className="flex flex-col items-center justify-center h-full w-full">
      <h2 className="text-3xl font-bold text-gray-700 mb-2">🎹 Build the Pinyin</h2>

      {/* Visual Cue */}
      <div className="flex items-center gap-4 mb-4">
         <img 
            src={PLACEHOLDER_IMAGES[currentItem.imageKeyword]} 
            alt={currentItem.english}
            className="w-20 h-20 object-cover rounded-xl border-2 border-white shadow-sm"
         />
         <div className="flex flex-col">
            <span className="text-2xl font-bold text-gray-800">{currentItem.chinese}</span>
            <AudioPlayer text={currentItem.chinese} autoPlay label="Listen" />
         </div>
      </div>

      {/* Input Display Area */}
      <div className="bg-white border-4 border-blue-200 rounded-2xl w-full max-w-md h-20 mb-6 flex items-center justify-center gap-1 shadow-inner overflow-hidden relative">
         {userInput.map((char, idx) => (
             <span key={idx} className="text-4xl font-bold text-blue-600 animate-in fade-in slide-in-from-bottom-2">
                 {char}
             </span>
         ))}
         {userInput.length === 0 && !isPenaltyActive && (
             <span className="text-gray-300 text-lg">Type letters below...</span>
         )}
         <span className="w-1 h-8 bg-blue-400 animate-pulse ml-1"></span>
      </div>

      {/* Controls Container */}
      <div className={`transition-opacity duration-300 ${isPenaltyActive ? 'opacity-20 pointer-events-none' : 'opacity-100'}`}>

          {/* Tone Bar */}
          <div className="flex gap-2 mb-4 justify-center">
             {['¯', '´', 'ˇ', '`'].map((symbol, idx) => (
                 <button
                    key={idx}
                    onClick={() => handleToneChange(idx)}
                    className="w-12 h-12 rounded-xl bg-orange-100 hover:bg-orange-200 border-b-4 border-orange-300 text-2xl font-bold text-orange-800 btn-press"
                 >
                    {symbol}
                 </button>
             ))}
             <button
                onClick={() => handleToneChange(4)} // Neutral tone
                className="w-12 h-12 rounded-xl bg-orange-50 hover:bg-orange-100 border-b-4 border-orange-200 text-sm font-bold text-orange-600 btn-press flex items-center justify-center"
             >
                None
             </button>
          </div>

          {/* Letter Keyboard */}
          <div className="grid grid-cols-6 gap-2 mb-6 max-w-md">
             {letterPool.map((char, idx) => (
                 <button
                    key={`${char}-${idx}`}
                    onClick={() => handleAddLetter(char)}
                    // Removed 'uppercase' class here
                    className="w-12 h-12 rounded-xl bg-blue-50 hover:bg-blue-100 border-b-4 border-blue-200 text-xl font-bold text-blue-700 btn-press"
                 >
                    {char}
                 </button>
             ))}
             <button
                onClick={handleBackspace}
                className="col-span-2 bg-red-100 hover:bg-red-200 border-b-4 border-red-300 rounded-xl font-bold text-red-600 btn-press flex items-center justify-center gap-1"
             >
                ⌫ Del
             </button>
          </div>

          {/* Submit Button */}
          <button
            onClick={checkAnswer}
            disabled={userInput.length === 0}
            className={`
                w-full max-w-md py-4 rounded-2xl font-bold text-xl text-white transition-all
                ${userInput.length === 0 
                    ? 'bg-gray-300 cursor-not-allowed' 
                    : 'bg-green-500 hover:bg-green-600 border-b-4 border-green-700 btn-press'}
            `}
          >
            Check Answer ✅
          </button>
      </div>

      {/* Penalty Overlay */}
      {isPenaltyActive && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
           <div className="bg-white rounded-[2rem] p-8 border-8 border-yellow-400 shadow-2xl flex flex-col items-center w-full max-w-sm animate-bounce-small">
              <div className="text-6xl mb-2">🙈</div>
              <h3 className="text-2xl font-bold text-gray-600 mb-2">Oops! Correct answer:</h3>

              <div className="text-6xl font-bold text-blue-600 mb-6 tracking-wider">
                  {currentItem.pinyin}
              </div>

              <div className="w-full bg-gray-200 rounded-full h-4 mb-4 overflow-hidden">
                  <div 
                    className="bg-red-500 h-full transition-all duration-1000 ease-linear"
                    style={{ width: `${(penaltyTime / 10) * 100}%` }}
                  ></div>
              </div>

              <p className="text-lg font-bold text-gray-500">
                  Try again in <span className="text-red-500 text-2xl">{penaltyTime}</span> seconds
              </p>

              {penaltyTime === 0 && (
                  <button 
                    onClick={() => {
                        setPenaltyTime(0);
                        setUserInput([]); // Clear input to restart
                    }}
                    className="mt-4 px-8 py-3 bg-blue-500 text-white font-bold rounded-xl border-b-4 border-blue-700 btn-press"
                  >
                      Try Again 🔄
                  </button>
              )}
           </div>
        </div>
      )}

      <div className="mt-6 text-gray-400 font-bold">
        {currentIndex + 1} / {data.length}
      </div>
    </div>
  );
};

export default PinyinPractice;

import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import PinyinPractice from './components/PinyinPractice';
import SpeakingPractice from './components/SpeakingPractice';
import Quiz from './components/Quiz';
import DialoguePractice from './components/DialoguePractice';
import TeacherReport from './components/TeacherReport';
import { ActivityType, SubmissionRecord, Lesson, SavedReport } from './types';
import { LESSONS, SOUNDS } from './constants';
import { createSavedReport, saveReportToCloud, getReportFromCloud } from './services/reportService';

interface AIStudioWindow {
  aistudio?: {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  };
}

const App: React.FC = () => {
  const [activity, setActivity] = useState<ActivityType>(ActivityType.LESSON_SELECT);
  const [currentLessonId, setCurrentLessonId] = useState<number | null>(null);
  const [submissions, setSubmissions] = useState<SubmissionRecord[]>([]);
  const [hasApiKey, setHasApiKey] = useState(false);
  const [completedLessons, setCompletedLessons] = useState<number[]>([]);

  // Teacher View State
  const [teacherReport, setTeacherReport] = useState<SavedReport | null>(null);
  const [isLoadingReport, setIsLoadingReport] = useState(false);
  const [generatedLink, setGeneratedLink] = useState<string | null>(null);
  const [isGeneratingLink, setIsGeneratingLink] = useState(false);
  const [isLocalFallback, setIsLocalFallback] = useState(false);

  useEffect(() => {
    // 1. Check for API Key
    const checkKey = async () => {
      const win = window as unknown as AIStudioWindow;
      if (win.aistudio) {
        const has = await win.aistudio.hasSelectedApiKey();
        setHasApiKey(has);
      } else {
        setHasApiKey(true);
      }
    };
    checkKey();

    // 2. Check for Report Link (Teacher View)
    const params = new URLSearchParams(window.location.search);
    const reportId = params.get('reportId');
    if (reportId) {
        setIsLoadingReport(true);
        // Async fetch from cloud
        getReportFromCloud(reportId)
            .then(savedReport => {
                if (savedReport) {
                    setTeacherReport(savedReport);
                    setActivity(ActivityType.TEACHER_REVIEW);
                } else {
                    alert("Report not found or expired.");
                }
            })
            .catch(err => {
                console.error(err);
                alert("Error loading report. Please check your connection.");
            })
            .finally(() => {
                setIsLoadingReport(false);
            });
    }
  }, []);

  const handleSelectKey = async () => {
    const win = window as unknown as AIStudioWindow;
    if (win.aistudio) {
      await win.aistudio.openSelectKey();
      setHasApiKey(true);
    }
  };

  const getActiveLesson = (): Lesson => {
    if (teacherReport) {
        return LESSONS.find(l => l.id === teacherReport.lessonId) || LESSONS[0];
    }
    return LESSONS.find(l => l.id === currentLessonId) || LESSONS[0];
  };

  const handleLessonSelect = (id: number) => {
    setCurrentLessonId(id);
    setSubmissions([]); 
    setGeneratedLink(null);
    setIsLocalFallback(false);
    setActivity(ActivityType.MENU);
  };

  const handleActivityComplete = (newRecords?: SubmissionRecord[]) => {
    if (newRecords) {
      setSubmissions(prev => [...prev, ...newRecords]);
    }
    new Audio(SOUNDS.SUCCESS).play();

    switch (activity) {
        case ActivityType.PINYIN:
            setActivity(ActivityType.SPEAKING);
            break;
        case ActivityType.SPEAKING:
            setActivity(ActivityType.QUIZ);
            break;
        case ActivityType.QUIZ:
            setActivity(ActivityType.DIALOGUE);
            break;
        case ActivityType.DIALOGUE:
            setActivity(ActivityType.SUMMARY);
            break;
        default:
            setActivity(ActivityType.MENU);
            break;
    }
  };

  const calculateScore = () => {
    return submissions.length * 10;
  };

  const handleFinishLesson = () => {
     setActivity(ActivityType.SUMMARY);
  };

  const handleGenerateLink = async () => {
    if (isGeneratingLink) return;
    setIsGeneratingLink(true);
    setGeneratedLink(null);
    setIsLocalFallback(false);

    try {
        const lesson = getActiveLesson();
        // Convert submission data to saveable format
        const report = await createSavedReport(lesson.id, "Student", submissions);

        // Save to cloud (returns ID)
        const id = await saveReportToCloud(report);

        // Check if it was a local fallback
        if (id.startsWith('local_')) {
            setIsLocalFallback(true);
        }

        // Create link
        const url = `${window.location.origin}${window.location.pathname}?reportId=${id}`;
        setGeneratedLink(url);
    } catch (error) {
        console.error(error);
        alert("Could not generate link. Please check your internet connection.");
    } finally {
        setIsGeneratingLink(false);
    }
  };

  const handleCopyLink = () => {
      if (generatedLink) {
          navigator.clipboard.writeText(generatedLink);
          alert(isLocalFallback 
            ? "Link copied! Warning: This link only works on THIS device."
            : "Link copied! You can share this with your teacher anywhere. 🌍");
      }
  };

  const handleCloseLesson = () => {
    if (currentLessonId !== null) {
        if (!completedLessons.includes(currentLessonId)) {
            setCompletedLessons(prev => [...prev, currentLessonId]);
        }
    }
    setCurrentLessonId(null);
    setSubmissions([]);
    setGeneratedLink(null);
    setActivity(ActivityType.LESSON_SELECT);

    // Clear URL param if we were in teacher mode
    if (activity === ActivityType.TEACHER_REVIEW) {
        window.history.pushState({}, '', window.location.pathname);
        setTeacherReport(null);
    }
  };

  // Navigation Handlers
  const handleBack = () => {
      if (activity === ActivityType.TEACHER_REVIEW) {
          handleCloseLesson();
          return;
      }

      if (
          activity === ActivityType.PINYIN || 
          activity === ActivityType.SPEAKING || 
          activity === ActivityType.QUIZ || 
          activity === ActivityType.DIALOGUE || 
          activity === ActivityType.SUMMARY
      ) {
          setActivity(ActivityType.MENU);
      } 
      else if (activity === ActivityType.MENU) {
          handleCloseLesson();
      }
  };

  const handlePrevLesson = () => {
      if (currentLessonId && currentLessonId > 1) {
          const prevId = currentLessonId - 1;
          handleLessonSelect(prevId);
      } else {
          alert("This is the first lesson!");
      }
  };

  const handleDirectNavigate = (type: ActivityType) => {
      setActivity(type);
  };

  const renderContent = () => {
    // If loading report from URL
    if (isLoadingReport) {
        return (
            <div className="flex flex-col items-center justify-center h-full">
                <div className="text-6xl animate-spin mb-4">🐼</div>
                <h2 className="text-2xl font-bold text-gray-500">Loading Teacher Report...</h2>
            </div>
        );
    }

    const activeLesson = getActiveLesson();

    switch (activity) {
      case ActivityType.TEACHER_REVIEW:
        return teacherReport ? <TeacherReport report={teacherReport} onBack={handleCloseLesson} /> : <div>Report not found.</div>;

      case ActivityType.LESSON_SELECT:
        return (
            <div className="w-full">
                <h2 className="text-3xl font-bold text-gray-700 mb-6 text-center">📚 Choose a Lesson</h2>
                <div className="grid grid-cols-1 gap-6">
                    {LESSONS.map(lesson => (
                        <button
                            key={lesson.id}
                            onClick={() => handleLessonSelect(lesson.id)}
                            className="bg-white hover:bg-blue-50 border-4 border-blue-200 rounded-3xl p-6 text-left shadow-sm btn-press flex justify-between items-center group"
                        >
                            <div>
                                <h3 className="text-2xl font-bold text-blue-600 group-hover:text-blue-700">{lesson.title}</h3>
                                <p className="text-gray-500 mt-2">{lesson.description}</p>
                            </div>
                            {completedLessons.includes(lesson.id) && (
                                <span className="text-4xl">✅</span>
                            )}
                            {!completedLessons.includes(lesson.id) && (
                                <span className="text-4xl opacity-20 group-hover:opacity-50">▶️</span>
                            )}
                        </button>
                    ))}
                </div>
            </div>
        );

      case ActivityType.MENU:
        return (
          <div className="w-full">
            <h2 className="text-2xl font-bold text-gray-400 mb-4 text-center uppercase tracking-widest">{activeLesson.title}</h2>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 p-4">
                <MenuButton 
                label="Step 1"
                title="✍️ 拼音书写" 
                subtitle="Build Pinyin" 
                color="bg-blue-400"
                onClick={() => setActivity(ActivityType.PINYIN)} 
                />
                <MenuButton 
                label="Step 2"
                title="🎤 口语跟读" 
                subtitle="Listen & Repeat" 
                color="bg-green-400"
                onClick={() => setActivity(ActivityType.SPEAKING)} 
                />
                <MenuButton 
                label="Step 3"
                title="🧩 听音辨意" 
                subtitle="Match Meanings" 
                color="bg-purple-400"
                onClick={() => setActivity(ActivityType.QUIZ)} 
                />
                <MenuButton 
                label="Step 4"
                title="💬 情景对话" 
                subtitle="Role Play" 
                color="bg-pink-400"
                onClick={() => setActivity(ActivityType.DIALOGUE)} 
                />
            </div>

            <div className="mt-8 flex justify-center">
                <button 
                    onClick={handleFinishLesson}
                    disabled={submissions.length === 0}
                    className={`
                        w-full max-w-lg px-8 py-5 rounded-2xl font-bold text-xl text-white shadow-lg btn-press flex flex-col items-center justify-center
                        ${submissions.length > 0 ? 'bg-yellow-400 hover:bg-yellow-500 border-b-4 border-yellow-600' : 'bg-gray-300 border-gray-400 cursor-not-allowed'}
                    `}
                >
                    <span className="text-2xl mb-1">✅ Save Homework & Share</span>
                    <span className="text-sm opacity-90 font-normal">(Finish all steps to submit to teacher)</span>
                </button>
            </div>
            <div className="text-center mt-2 text-gray-400 text-sm">
                You must complete at least one activity to save.
            </div>
          </div>
        );

      case ActivityType.PINYIN:
        return <PinyinPractice data={activeLesson.vocabulary} onComplete={handleActivityComplete} />;
      case ActivityType.SPEAKING:
        return <SpeakingPractice data={activeLesson.vocabulary} onComplete={handleActivityComplete} />;
      case ActivityType.QUIZ:
        return <Quiz data={activeLesson.vocabulary} onComplete={() => handleActivityComplete()} />;
      case ActivityType.DIALOGUE:
        return <DialoguePractice data={activeLesson.dialogues} onComplete={(records) => handleActivityComplete(records)} />;

      case ActivityType.SUMMARY:
        return (
          <div className="flex flex-col items-center justify-center h-full text-center w-full">
             <div className="text-6xl mb-4">🎉</div>
             <h2 className="text-3xl font-bold text-blue-600 mb-2">Lesson Complete!</h2>
             <p className="text-xl text-gray-600 mb-6">{activeLesson.title}</p>

             <div className="bg-white p-6 rounded-2xl border-4 border-yellow-200 shadow-inner w-full max-w-md mb-8">
                 <div className="flex justify-between items-center mb-4 border-b pb-2">
                     <span className="text-gray-500 font-bold">Activities Done</span>
                     <span className="text-2xl font-bold text-green-500">{submissions.length}</span>
                 </div>
                 <div className="flex justify-between items-center">
                     <span className="text-gray-500 font-bold">Total Score</span>
                     <span className="text-2xl font-bold text-purple-500">{calculateScore()}</span>
                 </div>
             </div>

             <div className="flex flex-col gap-4 w-full max-w-sm">
                {!generatedLink ? (
                    <button 
                      onClick={handleGenerateLink}
                      disabled={isGeneratingLink}
                      className="w-full py-4 rounded-2xl font-bold text-xl text-white bg-green-500 hover:bg-green-600 border-b-4 border-green-700 btn-press flex items-center justify-center gap-2"
                    >
                      <span>🔗</span> {isGeneratingLink ? 'Saving to Cloud...' : 'Create Teacher Link'}
                    </button>
                ) : (
                    <div className={`p-4 rounded-xl border-2 animate-in fade-in zoom-in ${isLocalFallback ? 'bg-orange-50 border-orange-200' : 'bg-green-50 border-green-200'}`}>
                        <p className={`text-sm font-bold mb-2 ${isLocalFallback ? 'text-orange-800' : 'text-green-800'}`}>
                           {isLocalFallback ? '⚠️ Network Error: Saved Locally Only' : 'Homework Saved Webpage!'}
                        </p>
                        <div className="flex gap-2">
                            <input 
                                readOnly 
                                value={generatedLink} 
                                className="flex-1 bg-white border border-gray-300 rounded-lg px-2 text-sm text-gray-500"
                            />
                            <button 
                                onClick={handleCopyLink}
                                className={`text-white px-4 py-2 rounded-lg font-bold ${isLocalFallback ? 'bg-orange-500 hover:bg-orange-600' : 'bg-green-500 hover:bg-green-600'}`}
                            >
                                Copy
                            </button>
                        </div>
                        <p className="text-xs text-gray-400 mt-2 text-center">
                            {isLocalFallback ? '(This link only works on THIS device)' : '(Share this link with your teacher to review remotely)'}
                        </p>
                    </div>
                )}

                <button 
                  onClick={handleCloseLesson}
                  className="w-full py-4 rounded-2xl font-bold text-xl text-gray-600 bg-gray-200 hover:bg-gray-300 border-b-4 border-gray-400 btn-press"
                >
                  Back to Lessons
                </button>
             </div>
          </div>
        );
      default:
        return null;
    }
  };

  if (!hasApiKey) {
    return (
        <Layout currentActivity={ActivityType.MENU} onHome={() => {}}>
            <div className="flex flex-col items-center justify-center h-full text-center">
                <h2 className="text-3xl font-bold text-gray-700 mb-6">Welcome to Panda Class! 🐼</h2>
                <p className="text-gray-500 mb-8 text-xl">Please connect your API Key to start.</p>
                <button 
                    onClick={handleSelectKey}
                    className="bg-blue-500 hover:bg-blue-600 text-white text-xl font-bold py-4 px-8 rounded-full border-b-4 border-blue-700 btn-press shadow-lg"
                >
                    🔑 Connect API Key
                </button>
            </div>
        </Layout>
    );
  }

  return (
    <Layout 
        currentActivity={activity} 
        onHome={() => {
            setActivity(ActivityType.LESSON_SELECT);
            setCurrentLessonId(null);
            setTeacherReport(null);
            window.history.pushState({}, '', window.location.pathname); // clear url
        }}
        showNav={currentLessonId !== null || teacherReport !== null}
        onBack={handleBack}
        onPrevLesson={handlePrevLesson}
        onNavigate={handleDirectNavigate}
    >
      {renderContent()}
    </Layout>
  );
};

const MenuButton: React.FC<{label: string; title: string; subtitle: string; color: string; onClick: () => void}> = ({ label, title, subtitle, color, onClick }) => (
  <button 
    onClick={onClick}
    className={`${color} hover:brightness-110 text-white p-6 rounded-[2rem] text-left border-b-8 border-black/20 btn-press flex flex-col justify-between h-40 sm:h-48`}
  >
    <div>
        <span className="text-xs sm:text-sm font-bold opacity-80 uppercase tracking-widest mb-1 block">{label}</span>
        <span className="text-2xl sm:text-3xl font-bold block mb-2">{title}</span>
    </div>
    <span className="text-md sm:text-lg opacity-90">{subtitle}</span>
  </button>
);

export default App;

export enum ActivityType {
  LESSON_SELECT = 'LESSON_SELECT',
  MENU = 'MENU',
  PINYIN = 'PINYIN',
  SPEAKING = 'SPEAKING',
  QUIZ = 'QUIZ',
  DIALOGUE = 'DIALOGUE',
  SUMMARY = 'SUMMARY',
  MODULE_SUCCESS = 'MODULE_SUCCESS', // New: Intermediate success screen
  TEACHER_REVIEW = 'TEACHER_REVIEW'
}

export interface VocabularyItem {
  id: string;
  chinese: string;
  pinyin: string;
  english: string;
  imageKeyword: string; 
}

export interface DialogueLine {
  speaker: 'A' | 'B';
  chinese: string;
  pinyin: string;
  english: string;
}

export interface DialogueGroup {
  id: string;
  lines: DialogueLine[];
}

export interface Lesson {
  id: number;
  title: string;
  description: string;
  vocabulary: VocabularyItem[];
  dialogues: DialogueGroup[];
}

export interface SubmissionRecord {
  type: 'writing' | 'speaking' | 'quiz' | 'dialogue';
  itemId: string;
  input: string | Blob; 
  score: number;
  feedback: string;
}

export interface FeedbackResponse {
  isCorrect: boolean;
  message: string;
}

// New: Saved format for storage/transmission (Blobs converted to Base64 strings)
export interface SavedSubmissionRecord {
  type: 'writing' | 'speaking' | 'quiz' | 'dialogue';
  itemId: string;
  input: string; // Base64 for audio/images, plain text for writing
  score: number;
  feedback: string;
}

export interface SavedReport {
  id: string;
  lessonId: number;
  studentName: string;
  timestamp: number;
  submissions: SavedSubmissionRecord[];
}

export interface LessonReport {
  lessonId: number;
  studentName: string;
  timestamp: string;
  totalScore: number;
  maxScore: number;
  details: string;
}

import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import PinyinPractice from './components/PinyinPractice';
import SpeakingPractice from './components/SpeakingPractice';
import Quiz from './components/Quiz';
import DialoguePractice from './components/DialoguePractice';
import TeacherReport from './components/TeacherReport';
import { ActivityType, SubmissionRecord, Lesson, SavedReport } from './types';
import { LESSONS, SOUNDS } from './constants';
import { createSavedReport, saveReportToCloud, getReportFromCloud } from './services/reportService';

interface AIStudioWindow {
  aistudio?: {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  };
}

const App: React.FC = () => {
  const [activity, setActivity] = useState<ActivityType>(ActivityType.LESSON_SELECT);
  const [currentLessonId, setCurrentLessonId] = useState<number | null>(null);
  const [submissions, setSubmissions] = useState<SubmissionRecord[]>([]);
  const [hasApiKey, setHasApiKey] = useState(false);
  const [completedLessons, setCompletedLessons] = useState<number[]>([]);

  // Navigation State
  const [nextActivity, setNextActivity] = useState<ActivityType>(ActivityType.MENU);

  // Teacher View State
  const [teacherReport, setTeacherReport] = useState<SavedReport | null>(null);
  const [isLoadingReport, setIsLoadingReport] = useState(false);
  const [generatedLink, setGeneratedLink] = useState<string | null>(null);
  const [isGeneratingLink, setIsGeneratingLink] = useState(false);
  const [isLocalFallback, setIsLocalFallback] = useState(false);

  useEffect(() => {
    // 1. Check for API Key
    const checkKey = async () => {
      const win = window as unknown as AIStudioWindow;
      if (win.aistudio) {
        const has = await win.aistudio.hasSelectedApiKey();
        setHasApiKey(has);
      } else {
        setHasApiKey(true);
      }
    };
    checkKey();

    // 2. Check for Report Link (Teacher View)
    const params = new URLSearchParams(window.location.search);
    const reportId = params.get('reportId');
    if (reportId) {
        setIsLoadingReport(true);
        // Async fetch from cloud
        getReportFromCloud(reportId)
            .then(savedReport => {
                if (savedReport) {
                    setTeacherReport(savedReport);
                    setActivity(ActivityType.TEACHER_REVIEW);
                } else {
                    alert("Report not found or expired.");
                }
            })
            .catch(err => {
                console.error(err);
                alert("Error loading report. Please check your connection.");
            })
            .finally(() => {
                setIsLoadingReport(false);
            });
    }
  }, []);

  const handleSelectKey = async () => {
    const win = window as unknown as AIStudioWindow;
    if (win.aistudio) {
      await win.aistudio.openSelectKey();
      setHasApiKey(true);
    }
  };

  const getActiveLesson = (): Lesson => {
    if (teacherReport) {
        return LESSONS.find(l => l.id === teacherReport.lessonId) || LESSONS[0];
    }
    return LESSONS.find(l => l.id === currentLessonId) || LESSONS[0];
  };

  const handleLessonSelect = (id: number) => {
    setCurrentLessonId(id);
    setSubmissions([]); 
    setGeneratedLink(null);
    setIsLocalFallback(false);
    setActivity(ActivityType.MENU);
  };

  const handleActivityComplete = (newRecords?: SubmissionRecord[]) => {
    if (newRecords) {
      setSubmissions(prev => [...prev, ...newRecords]);
    }
    new Audio(SOUNDS.SUCCESS).play();

    // Determine next activity instead of auto-navigating
    let next = ActivityType.MENU;
    switch (activity) {
        case ActivityType.PINYIN:
            next = ActivityType.SPEAKING;
            break;
        case ActivityType.SPEAKING:
            next = ActivityType.QUIZ;
            break;
        case ActivityType.QUIZ:
            next = ActivityType.DIALOGUE;
            break;
        case ActivityType.DIALOGUE:
            next = ActivityType.SUMMARY;
            break;
        default:
            next = ActivityType.MENU;
            break;
    }

    setNextActivity(next);
    // Reset link state for the new completion screen
    setGeneratedLink(null); 
    setActivity(ActivityType.MODULE_SUCCESS);
  };

  const handleContinue = () => {
      setActivity(nextActivity);
  };

  const calculateScore = () => {
    return submissions.length * 10;
  };

  const handleFinishLesson = () => {
     setActivity(ActivityType.SUMMARY);
  };

  const handleGenerateLink = async () => {
    if (isGeneratingLink) return;
    setIsGeneratingLink(true);
    setGeneratedLink(null);
    setIsLocalFallback(false);

    try {
        const lesson = getActiveLesson();
        // Convert submission data to saveable format
        const report = await createSavedReport(lesson.id, "Student", submissions);

        // Save to cloud (returns ID)
        const id = await saveReportToCloud(report);

        // Check if it was a local fallback
        if (id.startsWith('local_')) {
            setIsLocalFallback(true);
        }

        // Create link
        const url = `${window.location.origin}${window.location.pathname}?reportId=${id}`;
        setGeneratedLink(url);
    } catch (error) {
        console.error(error);
        alert("Could not generate link. Please check your internet connection.");
    } finally {
        setIsGeneratingLink(false);
    }
  };

  const handleCopyLink = () => {
      if (generatedLink) {
          navigator.clipboard.writeText(generatedLink);
          alert(isLocalFallback 
            ? "Link copied! Warning: This link only works on THIS device."
            : "Link copied! You can share this with your teacher anywhere. 🌍");
      }
  };

  const handleCloseLesson = () => {
    if (currentLessonId !== null) {
        if (!completedLessons.includes(currentLessonId)) {
            setCompletedLessons(prev => [...prev, currentLessonId]);
        }
    }
    setCurrentLessonId(null);
    setSubmissions([]);
    setGeneratedLink(null);
    setActivity(ActivityType.LESSON_SELECT);

    // Clear URL param if we were in teacher mode
    if (activity === ActivityType.TEACHER_REVIEW) {
        window.history.pushState({}, '', window.location.pathname);
        setTeacherReport(null);
    }
  };

  // Navigation Handlers
  const handleBack = () => {
      if (activity === ActivityType.TEACHER_REVIEW) {
          handleCloseLesson();
          return;
      }

      if (
          activity === ActivityType.PINYIN || 
          activity === ActivityType.SPEAKING || 
          activity === ActivityType.QUIZ || 
          activity === ActivityType.DIALOGUE || 
          activity === ActivityType.SUMMARY ||
          activity === ActivityType.MODULE_SUCCESS
      ) {
          setActivity(ActivityType.MENU);
      } 
      else if (activity === ActivityType.MENU) {
          handleCloseLesson();
      }
  };

  const handlePrevLesson = () => {
      if (currentLessonId && currentLessonId > 1) {
          const prevId = currentLessonId - 1;
          handleLessonSelect(prevId);
      } else {
          alert("This is the first lesson!");
      }
  };

  const handleDirectNavigate = (type: ActivityType) => {
      setActivity(type);
  };

  const renderContent = () => {
    // If loading report from URL
    if (isLoadingReport) {
        return (
            <div className="flex flex-col items-center justify-center h-full">
                <div className="text-6xl animate-spin mb-4">🐼</div>
                <h2 className="text-2xl font-bold text-gray-500">Loading Teacher Report...</h2>
            </div>
        );
    }

    const activeLesson = getActiveLesson();

    switch (activity) {
      case ActivityType.TEACHER_REVIEW:
        return teacherReport ? <TeacherReport report={teacherReport} onBack={handleCloseLesson} /> : <div>Report not found.</div>;

      case ActivityType.LESSON_SELECT:
        return (
            <div className="w-full">
                <h2 className="text-3xl font-bold text-gray-700 mb-6 text-center">📚 Choose a Lesson</h2>
                <div className="grid grid-cols-1 gap-6">
                    {LESSONS.map(lesson => (
                        <button
                            key={lesson.id}
                            onClick={() => handleLessonSelect(lesson.id)}
                            className="bg-white hover:bg-blue-50 border-4 border-blue-200 rounded-3xl p-6 text-left shadow-sm btn-press flex justify-between items-center group"
                        >
                            <div>
                                <h3 className="text-2xl font-bold text-blue-600 group-hover:text-blue-700">{lesson.title}</h3>
                                <p className="text-gray-500 mt-2">{lesson.description}</p>
                            </div>
                            {completedLessons.includes(lesson.id) && (
                                <span className="text-4xl">✅</span>
                            )}
                            {!completedLessons.includes(lesson.id) && (
                                <span className="text-4xl opacity-20 group-hover:opacity-50">▶️</span>
                            )}
                        </button>
                    ))}
                </div>
            </div>
        );

      case ActivityType.MENU:
        return (
          <div className="w-full">
            <h2 className="text-2xl font-bold text-gray-400 mb-4 text-center uppercase tracking-widest">{activeLesson.title}</h2>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 p-4">
                <MenuButton 
                label="Step 1"
                title="✍️ 拼音书写" 
                subtitle="Build Pinyin" 
                color="bg-blue-400"
                onClick={() => setActivity(ActivityType.PINYIN)} 
                />
                <MenuButton 
                label="Step 2"
                title="🎤 口语跟读" 
                subtitle="Listen & Repeat" 
                color="bg-green-400"
                onClick={() => setActivity(ActivityType.SPEAKING)} 
                />
                <MenuButton 
                label="Step 3"
                title="🧩 听音辨意" 
                subtitle="Match Meanings" 
                color="bg-purple-400"
                onClick={() => setActivity(ActivityType.QUIZ)} 
                />
                <MenuButton 
                label="Step 4"
                title="💬 情景对话" 
                subtitle="Role Play" 
                color="bg-pink-400"
                onClick={() => setActivity(ActivityType.DIALOGUE)} 
                />
            </div>

            <div className="mt-8 flex justify-center">
                <button 
                    onClick={handleFinishLesson}
                    disabled={submissions.length === 0}
                    className={`
                        w-full max-w-lg px-8 py-5 rounded-2xl font-bold text-xl text-white shadow-lg btn-press flex flex-col items-center justify-center
                        ${submissions.length > 0 ? 'bg-yellow-400 hover:bg-yellow-500 border-b-4 border-yellow-600' : 'bg-gray-300 border-gray-400 cursor-not-allowed'}
                    `}
                >
                    <span className="text-2xl mb-1">✅ Save Homework & Share</span>
                    <span className="text-sm opacity-90 font-normal">(Get link for teacher)</span>
                </button>
            </div>
            <div className="text-center mt-2 text-gray-400 text-sm">
                Complete modules to save progress.
            </div>
          </div>
        );

      case ActivityType.MODULE_SUCCESS:
        return (
          <div className="flex flex-col items-center justify-center h-full text-center w-full">
             <div className="text-6xl mb-4">🌟</div>
             <h2 className="text-3xl font-bold text-blue-600 mb-4">Good Job!</h2>
             <p className="text-gray-600 mb-8 max-w-sm">
                 You have completed this module. You can continue to the next part, or submit your homework to the teacher now.
             </p>

             <div className="flex flex-col gap-4 w-full max-w-sm">

                 {/* Next Button */}
                 {nextActivity !== ActivityType.MENU && nextActivity !== ActivityType.SUMMARY && (
                    <button 
                        onClick={handleContinue}
                        className="w-full py-4 rounded-2xl font-bold text-xl text-white bg-blue-500 hover:bg-blue-600 border-b-4 border-blue-700 btn-press flex items-center justify-center gap-2"
                    >
                        Next Activity ➡️
                    </button>
                 )}
                 {/* If next is Summary, just show Continue */}
                 {(nextActivity === ActivityType.SUMMARY) && (
                    <button 
                        onClick={handleContinue}
                        className="w-full py-4 rounded-2xl font-bold text-xl text-white bg-blue-500 hover:bg-blue-600 border-b-4 border-blue-700 btn-press flex items-center justify-center gap-2"
                    >
                        Finish Lesson 🏁
                    </button>
                 )}

                 {/* Submit Button */}
                 {!generatedLink ? (
                    <button 
                      onClick={handleGenerateLink}
                      disabled={isGeneratingLink}
                      className="w-full py-4 rounded-2xl font-bold text-xl text-yellow-700 bg-yellow-300 hover:bg-yellow-400 border-b-4 border-yellow-500 btn-press flex items-center justify-center gap-2"
                    >
                      <span>📮</span> {isGeneratingLink ? 'Saving...' : 'Submit to Teacher Now'}
                    </button>
                 ) : (
                    <div className={`p-4 rounded-xl border-2 animate-in fade-in zoom-in ${isLocalFallback ? 'bg-orange-50 border-orange-200' : 'bg-green-50 border-green-200'}`}>
                        <p className={`text-sm font-bold mb-2 ${isLocalFallback ? 'text-orange-800' : 'text-green-800'}`}>
                           {isLocalFallback ? '⚠️ Saved Locally Only' : 'Homework Submitted! Share this link:'}
                        </p>
                        <div className="flex gap-2">
                            <input 
                                readOnly 
                                value={generatedLink} 
                                className="flex-1 bg-white border border-gray-300 rounded-lg px-2 text-sm text-gray-500"
                            />
                            <button 
                                onClick={handleCopyLink}
                                className={`text-white px-4 py-2 rounded-lg font-bold ${isLocalFallback ? 'bg-orange-500 hover:bg-orange-600' : 'bg-green-500 hover:bg-green-600'}`}
                            >
                                Copy
                            </button>
                        </div>
                         <p className="text-xs text-gray-400 mt-2 text-center">
                            {isLocalFallback ? '(Link valid on THIS device)' : '(Teacher can view anywhere)'}
                        </p>
                    </div>
                 )}

                 <button 
                  onClick={() => setActivity(ActivityType.MENU)}
                  className="w-full py-3 text-gray-500 font-bold hover:text-gray-700"
                 >
                  Back to Menu
                 </button>
             </div>
          </div>
        );

      case ActivityType.PINYIN:
        return <PinyinPractice data={activeLesson.vocabulary} onComplete={handleActivityComplete} />;
      case ActivityType.SPEAKING:
        return <SpeakingPractice data={activeLesson.vocabulary} onComplete={handleActivityComplete} />;
      case ActivityType.QUIZ:
        return <Quiz data={activeLesson.vocabulary} onComplete={() => handleActivityComplete()} />;
      case ActivityType.DIALOGUE:
        return <DialoguePractice data={activeLesson.dialogues} onComplete={(records) => handleActivityComplete(records)} />;

      case ActivityType.SUMMARY:
        return (
          <div className="flex flex-col items-center justify-center h-full text-center w-full">
             <div className="text-6xl mb-4">🎉</div>
             <h2 className="text-3xl font-bold text-blue-600 mb-2">Lesson Complete!</h2>
             <p className="text-xl text-gray-600 mb-6">{activeLesson.title}</p>

             <div className="bg-white p-6 rounded-2xl border-4 border-yellow-200 shadow-inner w-full max-w-md mb-8">
                 <div className="flex justify-between items-center mb-4 border-b pb-2">
                     <span className="text-gray-500 font-bold">Activities Done</span>
                     <span className="text-2xl font-bold text-green-500">{submissions.length}</span>
                 </div>
                 <div className="flex justify-between items-center">
                     <span className="text-gray-500 font-bold">Total Score</span>
                     <span className="text-2xl font-bold text-purple-500">{calculateScore()}</span>
                 </div>
             </div>

             <div className="flex flex-col gap-4 w-full max-w-sm">
                {!generatedLink ? (
                    <button 
                      onClick={handleGenerateLink}
                      disabled={isGeneratingLink}
                      className="w-full py-4 rounded-2xl font-bold text-xl text-white bg-green-500 hover:bg-green-600 border-b-4 border-green-700 btn-press flex items-center justify-center gap-2"
                    >
                      <span>🔗</span> {isGeneratingLink ? 'Saving to Cloud...' : 'Create Teacher Link'}
                    </button>
                ) : (
                    <div className={`p-4 rounded-xl border-2 animate-in fade-in zoom-in ${isLocalFallback ? 'bg-orange-50 border-orange-200' : 'bg-green-50 border-green-200'}`}>
                        <p className={`text-sm font-bold mb-2 ${isLocalFallback ? 'text-orange-800' : 'text-green-800'}`}>
                           {isLocalFallback ? '⚠️ Network Error: Saved Locally Only' : 'Homework Saved Webpage!'}
                        </p>
                        <div className="flex gap-2">
                            <input 
                                readOnly 
                                value={generatedLink} 
                                className="flex-1 bg-white border border-gray-300 rounded-lg px-2 text-sm text-gray-500"
                            />
                            <button 
                                onClick={handleCopyLink}
                                className={`text-white px-4 py-2 rounded-lg font-bold ${isLocalFallback ? 'bg-orange-500 hover:bg-orange-600' : 'bg-green-500 hover:bg-green-600'}`}
                            >
                                Copy
                            </button>
                        </div>
                        <p className="text-xs text-gray-400 mt-2 text-center">
                            {isLocalFallback ? '(This link only works on THIS device)' : '(Share this link with your teacher to review remotely)'}
                        </p>
                    </div>
                )}

                <button 
                  onClick={handleCloseLesson}
                  className="w-full py-4 rounded-2xl font-bold text-xl text-gray-600 bg-gray-200 hover:bg-gray-300 border-b-4 border-gray-400 btn-press"
                >
                  Back to Lessons
                </button>
             </div>
          </div>
        );
      default:
        return null;
    }
  };

  if (!hasApiKey) {
    return (
        <Layout currentActivity={ActivityType.MENU} onHome={() => {}}>
            <div className="flex flex-col items-center justify-center h-full text-center">
                <h2 className="text-3xl font-bold text-gray-700 mb-6">Welcome to Panda Class! 🐼</h2>
                <p className="text-gray-500 mb-8 text-xl">Please connect your API Key to start.</p>
                <button 
                    onClick={handleSelectKey}
                    className="bg-blue-500 hover:bg-blue-600 text-white text-xl font-bold py-4 px-8 rounded-full border-b-4 border-blue-700 btn-press shadow-lg"
                >
                    🔑 Connect API Key
                </button>
            </div>
        </Layout>
    );
  }

  return (
    <Layout 
        currentActivity={activity} 
        onHome={() => {
            setActivity(ActivityType.LESSON_SELECT);
            setCurrentLessonId(null);
            setTeacherReport(null);
            window.history.pushState({}, '', window.location.pathname); // clear url
        }}
        showNav={currentLessonId !== null || teacherReport !== null}
        onBack={handleBack}
        onPrevLesson={handlePrevLesson}
        onNavigate={handleDirectNavigate}
    >
      {renderContent()}
    </Layout>
  );
};

