import { SubmissionRecord, SavedSubmissionRecord, SavedReport, Classroom, ClassSubmission } from '../types';
import { blobToBase64 } from './geminiService';

const JSONBLOB_API = 'https://jsonblob.com/api/jsonBlob';
const LOCAL_PREFIX = 'local_';

/**
 * Converts active session submissions (with Blobs) to a JSON-safe format (Base64).
 */
export const createSavedReport = async (
  lessonId: number, 
  studentName: string, 
  submissions: SubmissionRecord[]
): Promise<SavedReport> => {

  const savedSubmissions: SavedSubmissionRecord[] = await Promise.all(
    submissions.map(async (sub) => {
      let inputData = '';

      if (sub.input instanceof Blob) {
        inputData = await blobToBase64(sub.input);
      } else {
        inputData = String(sub.input);
      }

      return {
        type: sub.type,
        itemId: sub.itemId,
        input: inputData, // Now guaranteed to be a string
        score: sub.score,
        feedback: sub.feedback
      };
    })
  );

  const report: SavedReport = {
    id: crypto.randomUUID(),
    lessonId,
    studentName,
    timestamp: Date.now(),
    submissions: savedSubmissions
  };

  return report;
};

/**
 * Saves the report to "Cloud" (JsonBlob) so it can be shared remotely.
 * Fallback to LocalStorage if network fails.
 */
export const saveReportToCloud = async (report: SavedReport): Promise<string> => {
  try {
    const response = await fetch(JSONBLOB_API, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Accept': 'application/json'
      },
      body: JSON.stringify(report)
    });

    if (!response.ok) {
      throw new Error('Cloud save failed');
    }

    // The API returns the location of the new blob in the Location header
    const location = response.headers.get('Location');
    if (!location) throw new Error('No location header received');

    // Extract the ID from the URL (e.g. https://jsonblob.com/api/jsonBlob/<id>)
    const parts = location.split('/');
    const cloudId = parts[parts.length - 1];
    return cloudId;

  } catch (e) {
    console.warn("Cloud save failed, falling back to local storage.", e);
    // Fallback: Save locally
    const localId = `${LOCAL_PREFIX}${report.id}`;
    localStorage.setItem(localId, JSON.stringify(report));
    return localId;
  }
};

/**
 * Retrieves a report by ID. Checks if it's a local ID or a cloud ID.
 */
export const getReportFromCloud = async (reportId: string): Promise<SavedReport | null> => {
  // 1. Check if it's a local fallback ID
  if (reportId.startsWith(LOCAL_PREFIX)) {
    try {
        const data = localStorage.getItem(reportId);
        if (!data) return null;
        return JSON.parse(data) as SavedReport;
    } catch (e) {
        console.error("Local load failed", e);
        return null;
    }
  }

  // 2. Fetch from Cloud
  try {
    const response = await fetch(`${JSONBLOB_API}/${reportId}`, {
        headers: { 'Accept': 'application/json' }
    });

    if (!response.ok) return null;

    const data = await response.json();
    return data as SavedReport;
  } catch (e) {
    console.error("Cloud load failed", e);
    return null;
  }
};

/**
 * Helper to reconstruct a Blob from Base64 (for playing audio in Teacher View).
 */
export const base64ToBlob = (base64: string, mimeType: string = 'audio/webm'): Blob => {
  const byteCharacters = atob(base64);
  const byteNumbers = new Array(byteCharacters.length);
  for (let i = 0; i < byteCharacters.length; i++) {
    byteNumbers[i] = byteCharacters.charCodeAt(i);
  }
  const byteArray = new Uint8Array(byteNumbers);
  return new Blob([byteArray], { type: mimeType });
};

// --- Teacher Portal Services ---

/**
 * Creates a new classroom blob and returns the Class ID.
 */
export const createClassroom = async (name: string): Promise<string> => {
  const newClass: Classroom = {
    id: '', // Will be updated by caller logic or just rely on blob ID
    name,
    submissions: []
  };

  const response = await fetch(JSONBLOB_API, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
    body: JSON.stringify(newClass)
  });

  if (!response.ok) throw new Error('Failed to create class');

  const location = response.headers.get('Location');
  if (!location) throw new Error('No location');
  const parts = location.split('/');
  return parts[parts.length - 1];
};

/**
 * Fetches classroom data by Class ID.
 */
export const getClassroom = async (classId: string): Promise<Classroom | null> => {
   try {
    const response = await fetch(`${JSONBLOB_API}/${classId}`, {
        headers: { 'Accept': 'application/json' }
    });
    if (!response.ok) return null;
    const data = await response.json();
    return { ...data, id: classId }; // Ensure ID is consistent
  } catch (e) {
    return null;
  }
};

/**
 * Adds a student submission to a classroom blob.
 */
export const submitToClassroom = async (classId: string, submission: ClassSubmission): Promise<boolean> => {
  try {
    // 1. Fetch current class data
    const classroom = await getClassroom(classId);
    if (!classroom) return false;

    // 2. Check for duplicate submission (same reportId)
    const exists = classroom.submissions.some(s => s.reportId === submission.reportId);
    if (!exists) {
        classroom.submissions.push(submission);

        // 3. Update blob
        const response = await fetch(`${JSONBLOB_API}/${classId}`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
            body: JSON.stringify(classroom)
        });
        return response.ok;
    }
    return true; // Already exists is treated as success
  } catch (e) {
    console.error("Class submission failed", e);
    return false;
  }
};

