const HOMEWORK_LIST_KEY = 'teacher_homework_list';

export const getHomeworkList = (): HomeworkEntry[] => {
  const json = localStorage.getItem(HOMEWORK_LIST_KEY);
  return json ? JSON.parse(json) : [];
};

export const submitHomework = async (
  entry: HomeworkEntry, 
  videoBlob: Blob
): Promise<void> => {
  // 1. Save Video Blob to IndexedDB (handles large files)
  await saveVideoToDB(entry.videoId, videoBlob);

  // 2. Save Metadata to LocalStorage (Teacher List)
  const currentList = getHomeworkList();
  const newList = [entry, ...currentList];
  localStorage.setItem(HOMEWORK_LIST_KEY, JSON.stringify(newList));
};

