  const handleFinishLesson = () => {
     // If recording, stop it now
     if (isRecordingSession) {
         stopSessionRecording();
     }
     setActivity(ActivityType.SUMMARY);
  };

  const handleSaveHomework = async () => {
      if (!studentName.trim()) {
          alert("Please enter your name!");
          return;
      }
      if (!recordingBlob) {
          alert("No recording found! Did you start recording?");
          return;
      }

      setIsSubmitting(true);
      try {
          const videoId = `vid_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
          const entry: HomeworkEntry = {
              id: crypto.randomUUID(),
              studentName: studentName,
              lessonTitle: getActiveLesson().title,
              timestamp: Date.now(),
              score: calculateScore(),
              videoId: videoId
          };

          await submitHomework(entry, recordingBlob);
          setIsSubmitted(true);
      } catch (e) {
          console.error(e);
          alert("Failed to save homework.");
      } finally {
          setIsSubmitting(false);
      }
  };

  const handleCloseLesson = () => {
    if (isRecordingSession) stopSessionRecording();
    if (currentLessonId !== null && !completedLessons.includes(currentLessonId)) {
        setCompletedLessons(prev => [...prev, currentLessonId]);
    }
    setCurrentLessonId(null);
    setSubmissions([]);
    setRecordingBlob(null);
    setIsSubmitted(false);
    setActivity(ActivityType.LESSON_SELECT);
  };

  const handleBack = () => {
      if (activity === ActivityType.TEACHER_PORTAL) {
          setActivity(ActivityType.LESSON_SELECT);
          return;
      }
      if (
          activity === ActivityType.PINYIN || 
          activity === ActivityType.SPEAKING || 
          activity === ActivityType.QUIZ || 
          activity === ActivityType.DIALOGUE || 
          activity === ActivityType.SUMMARY ||
          activity === ActivityType.MODULE_SUCCESS
      ) {
          setActivity(ActivityType.MENU);
      } 
      else if (activity === ActivityType.MENU) {
          handleCloseLesson();
      }
  };

  const handleDirectNavigate = (type: ActivityType) => {
    setActivity(type);
  };

  const renderContent = () => {
    const activeLesson = getActiveLesson();

    switch (activity) {
      case ActivityType.TEACHER_PORTAL:
        return <TeacherPortal onBack={() => setActivity(ActivityType.LESSON_SELECT)} />;

      case ActivityType.LESSON_SELECT:
        return (
            <div className="w-full relative">
                 <div className="absolute top-0 right-0">
                    <button 
                        onClick={() => setActivity(ActivityType.TEACHER_PORTAL)}
                        className="text-sm font-bold text-blue-400 hover:text-blue-600 bg-white/80 px-4 py-2 rounded-full border border-blue-200 shadow-sm"
                    >
                        👨‍🏫 Teacher Portal
                    </button>
                </div>

                <h2 className="text-3xl font-bold text-gray-700 mb-6 text-center">📚 Choose a Lesson</h2>
                <div className="grid grid-cols-1 gap-6">
                    {LESSONS.map(lesson => (
                        <button
                            key={lesson.id}
                            onClick={() => handleLessonSelect(lesson.id)}
                            className="bg-white hover:bg-blue-50 border-4 border-blue-200 rounded-3xl p-6 text-left shadow-sm btn-press flex justify-between items-center group"
                        >
                            <div>
                                <h3 className="text-2xl font-bold text-blue-600 group-hover:text-blue-700">{lesson.title}</h3>
                                <p className="text-gray-500 mt-2">{lesson.description}</p>
                            </div>
                            {completedLessons.includes(lesson.id) && (
                                <span className="text-4xl">✅</span>
                            )}
                            {!completedLessons.includes(lesson.id) && (
                                <span className="text-4xl opacity-20 group-hover:opacity-50">▶️</span>
                            )}
                        </button>
                    ))}
                </div>
            </div>
        );

      case ActivityType.MENU:
        return (
          <div className="w-full">
            <h2 className="text-2xl font-bold text-gray-400 mb-2 text-center uppercase tracking-widest">{activeLesson.title}</h2>

            {/* Recording Control */}
            <div className="flex justify-center mb-6">
                {!isRecordingSession ? (
                    <button 
                        onClick={startSessionRecording}
                        className="bg-red-500 text-white font-bold py-3 px-6 rounded-full animate-bounce shadow-lg border-b-4 border-red-700 active:translate-y-1"
                    >
                        🔴 Start Recording Homework
                    </button>
                ) : (
                     <div className="bg-red-100 text-red-600 px-6 py-2 rounded-full font-mono font-bold border-2 border-red-200 flex items-center gap-2">
                         <span className="w-3 h-3 bg-red-600 rounded-full animate-pulse"></span>
                         Recording in progress...
                     </div>
                )}
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 p-4">
                <MenuButton label="Step 1" title="✍️ 拼音书写" subtitle="Build Pinyin" color="bg-blue-400" onClick={() => setActivity(ActivityType.PINYIN)} />
                <MenuButton label="Step 2" title="🎤 口语跟读" subtitle="Listen & Repeat" color="bg-green-400" onClick={() => setActivity(ActivityType.SPEAKING)} />
                <MenuButton label="Step 3" title="🧩 听音辨意" subtitle="Match Meanings" color="bg-purple-400" onClick={() => setActivity(ActivityType.QUIZ)} />
                <MenuButton label="Step 4" title="💬 情景对话" subtitle="Role Play" color="bg-pink-400" onClick={() => setActivity(ActivityType.DIALOGUE)} />
            </div>

            <div className="mt-8 flex justify-center">
                <button 
                    onClick={handleFinishLesson}
                    disabled={submissions.length === 0}
                    className={`
                        w-full max-w-lg px-8 py-5 rounded-2xl font-bold text-xl text-white shadow-lg btn-press flex flex-col items-center justify-center
                        ${submissions.length > 0 ? 'bg-yellow-400 hover:bg-yellow-500 border-b-4 border-yellow-600' : 'bg-gray-300 border-gray-400 cursor-not-allowed'}
                    `}
                >
                    <span className="text-2xl mb-1">🏁 Finish & Submit</span>
                    <span className="text-sm opacity-90 font-normal">
                        {isRecordingSession ? '(Stops recording)' : '(Review)'}
                    </span>
                </button>
            </div>
          </div>
        );

      case ActivityType.MODULE_SUCCESS:
      case ActivityType.SUMMARY:
        const isSummary = activity === ActivityType.SUMMARY;
        return (
          <div className="flex flex-col items-center justify-center h-full text-center w-full">
             <div className="text-6xl mb-4">{isSummary ? '🎉' : '🌟'}</div>
             <h2 className="text-3xl font-bold text-blue-600 mb-4">{isSummary ? 'Lesson Complete!' : 'Good Job!'}</h2>

             {isSummary && recordingBlob && !isSubmitted && (
                 <div className="bg-green-50 p-4 rounded-xl border-2 border-green-200 mb-6 w-full max-w-md">
                     <p className="font-bold text-green-800 mb-2">🎥 Screen Recording Ready!</p>
                     <video src={URL.createObjectURL(recordingBlob)} controls className="w-full rounded-lg mb-2 bg-black max-h-40" />
                     <p className="text-xs text-gray-500">Review your recording before submitting.</p>
                 </div>
             )}

             {isSummary && !recordingBlob && (
                 <div className="bg-red-50 p-4 rounded-xl border-2 border-red-200 mb-6 text-red-600 font-bold">
                     ⚠️ No screen recording found. Please record next time for full credit!
                 </div>
             )}

             <div className="flex flex-col gap-4 w-full max-w-sm">
                 {/* Next Button */}
                 {!isSummary && (
                    <button 
                        onClick={handleContinue}
                        className="w-full py-4 rounded-2xl font-bold text-xl text-white bg-blue-500 hover:bg-blue-600 border-b-4 border-blue-700 btn-press flex items-center justify-center gap-2"
                    >
                        {nextActivity === ActivityType.SUMMARY ? 'Finish Lesson 🏁' : 'Next Activity ➡️'}
                    </button>
                 )}

                 {/* Submit Section (Only on Summary) */}
                 {isSummary && !isSubmitted && recordingBlob && (
                    <div className="bg-yellow-50 p-6 rounded-2xl border-4 border-yellow-200 w-full">
                        <input 
                            value={studentName}
                            onChange={(e) => setStudentName(e.target.value)}
                            placeholder="Enter Student Name"
                            className="w-full p-4 mb-4 rounded-xl border-2 border-yellow-300 text-center font-bold text-xl"
                        />
                        <button 
                            onClick={handleSaveHomework}
                            disabled={isSubmitting || !studentName.trim()}
                            className="w-full py-4 rounded-xl font-bold text-xl text-yellow-900 bg-yellow-400 hover:bg-yellow-500 border-b-4 border-yellow-600 btn-press flex items-center justify-center gap-2 disabled:opacity-50"
                        >
                            <span>📮</span> {isSubmitting ? 'Sending...' : 'Submit to Teacher Portal'}
                        </button>
                    </div>
                 )}

                 {isSummary && isSubmitted && (
                     <div className="p-6 bg-green-100 rounded-2xl border-4 border-green-300 text-green-800 font-bold text-xl animate-in fade-in zoom-in">
                         ✅ Homework Submitted!
                     </div>
                 )}

                 <button 
                  onClick={handleCloseLesson}
                  className="w-full py-3 text-gray-500 font-bold hover:text-gray-700"
                 >
                  Back to Menu
                 </button>
             </div>
          </div>
        );

      case ActivityType.PINYIN:
        return <PinyinPractice data={activeLesson.vocabulary} onComplete={handleActivityComplete} />;
      case ActivityType.SPEAKING:
        return <SpeakingPractice data={activeLesson.vocabulary} onComplete={handleActivityComplete} />;
      case ActivityType.QUIZ:
        return <Quiz data={activeLesson.vocabulary} onComplete={() => handleActivityComplete()} />;
      case ActivityType.DIALOGUE:
        return <DialoguePractice data={activeLesson.dialogues} onComplete={(records) => handleActivityComplete(records)} />;

      default:
        return null;
    }
  };

  if (!hasApiKey) {
    return (
        <Layout currentActivity={ActivityType.MENU} onHome={() => {}}>
            <div className="flex flex-col items-center justify-center h-full text-center">
                <h2 className="text-3xl font-bold text-gray-700 mb-6">Welcome to Panda Class! 🐼</h2>
                <p className="text-gray-500 mb-8 text-xl">Please connect your API Key to start.</p>
                <button 
                    onClick={handleSelectKey}
                    className="bg-blue-500 hover:bg-blue-600 text-white text-xl font-bold py-4 px-8 rounded-full border-b-4 border-blue-700 btn-press shadow-lg"
                >
                    🔑 Connect API Key
                </button>
            </div>
        </Layout>
    );
  }

  return (
    <Layout 
        currentActivity={activity} 
        onHome={handleCloseLesson}
        showNav={currentLessonId !== null}
        onBack={handleBack}
        onNavigate={handleDirectNavigate}
    >
      {renderContent()}
    </Layout>
  );
};

