import React, { useState, useEffect, useMemo } from 'react';
import { VocabularyItem, SubmissionRecord } from '../types';
import AudioPlayer from './AudioPlayer';
import { speakText } from '../services/geminiService';
import { SOUNDS, PLACEHOLDER_IMAGES } from '../constants';

interface Props {
  data: VocabularyItem[];
  onComplete: () => void;
  onRecord: (record: SubmissionRecord) => void;
}

// Map base vowels to their toned versions [flat, rising, dipping, falling, neutral]
const TONE_MAP: Record<string, string[]> = {
  'a': ['ā', 'á', 'ǎ', 'à', 'a'],
  'e': ['ē', 'é', 'ě', 'è', 'e'],
  'i': ['ī', 'í', 'ǐ', 'ì', 'i'],
  'o': ['ō', 'ó', 'ǒ', 'ò', 'o'],
  'u': ['ū', 'ú', 'ǔ', 'ù', 'u'],
  'ü': ['ǖ', 'ǘ', 'ǚ', 'ǜ', 'ü'],
};

// Helper to get base char (e.g., 'á' -> 'a')
const getBaseChar = (char: string): string => {
  for (const [base, variants] of Object.entries(TONE_MAP)) {
    if (variants.includes(char)) return base;
  }
  return char;
};

const PinyinPractice: React.FC<Props> = ({ data, onComplete, onRecord }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [userInput, setUserInput] = useState<string[]>([]); // Array of chars for easier manipulation
  const [penaltyTime, setPenaltyTime] = useState(0); 

  const currentItem = data[currentIndex];

  // Timer effect for penalty
  useEffect(() => {
    let timer: number;
    if (penaltyTime > 0) {
      timer = window.setInterval(() => {
        setPenaltyTime((prev) => prev - 1);
      }, 1000);
    }
    return () => clearInterval(timer);
  }, [penaltyTime]);

  // Generate a pool of letters based on the target word + some distractors
  const letterPool = useMemo(() => {
    // Get unique base chars from the pinyin, ignoring spaces
    const targetChars = currentItem.pinyin.replace(/\s/g, '').split('').map(getBaseChar);
    const uniqueChars = Array.from(new Set(targetChars));

    // Add some common pinyin letters as distractors
    const commonDistractors = ['a', 'o', 'e', 'i', 'u', 'b', 'p', 'm', 'f', 'd', 't', 'n', 'l', 'g', 'k', 'h', 'j', 'q', 'x'];

    // Fill up to 12 letters if needed
    while (uniqueChars.length < 12) {
        const randomChar = commonDistractors[Math.floor(Math.random() * commonDistractors.length)];
        if (!uniqueChars.includes(randomChar)) {
            uniqueChars.push(randomChar);
        }
    }

    // Shuffle
    return uniqueChars.sort(() => 0.5 - Math.random());
  }, [currentItem]);

  // Reset input when word changes
  useEffect(() => {
    setUserInput([]);
    setPenaltyTime(0);
  }, [currentIndex]);

  const handleAddLetter = (char: string) => {
    if (penaltyTime > 0) return;
    setUserInput(prev => [...prev, char]);
  };

  const handleBackspace = () => {
    if (penaltyTime > 0) return;
    setUserInput(prev => prev.slice(0, -1));
  };

  const handleToneChange = (toneIndex: number) => {
    if (penaltyTime > 0 || userInput.length === 0) return;

    // Modify the LAST character if it's a vowel
    const lastChar = userInput[userInput.length - 1];
    const base = getBaseChar(lastChar);

    if (TONE_MAP[base]) {
        const newChar = TONE_MAP[base][toneIndex];
        const newInput = [...userInput];
        newInput[newInput.length - 1] = newChar;
        setUserInput(newInput);
    }
  };

  const checkAnswer = () => {
    const inputString = userInput.join('');
    // Remove spaces from target since we track input without spaces
    const targetString = currentItem.pinyin.replace(/\s/g, '');

    if (inputString === targetString) {
      // Correct!
      new Audio(SOUNDS.CORRECT).play();
      speakText("Excellent!", "en-US");

      const newRecord: SubmissionRecord = {
        type: 'writing',
        itemId: currentItem.id,
        input: inputString,
        score: 1,
        feedback: "Correct Pinyin Construction"
      };

      onRecord(newRecord);

      // Delay slightly before next
      setTimeout(() => {
        if (currentIndex < data.length - 1) {
            setCurrentIndex(prev => prev + 1);
        } else {
            onComplete();
        }
      }, 1500);

    } else {
      // Wrong!
      new Audio(SOUNDS.WRONG).play();
      speakText("Not quite. Look at the correct answer!", "en-US");
      setPenaltyTime(10); // Start 10s penalty
    }
  };

  const isPenaltyActive = penaltyTime > 0;

  return (
    <div className="flex flex-col items-center justify-center h-full w-full">
      <h2 className="text-3xl font-bold text-gray-700 mb-2">🎹 Build the Pinyin</h2>

      {/* Visual Cue */}
      <div className="flex items-center gap-4 mb-4">
         <img 
            src={PLACEHOLDER_IMAGES[currentItem.imageKeyword]} 
            alt={currentItem.english}
            className="w-20 h-20 object-cover rounded-xl border-2 border-white shadow-sm"
         />
         <div className="flex flex-col">
            <span className="text-2xl font-bold text-gray-800">{currentItem.chinese}</span>
            <AudioPlayer text={currentItem.chinese} autoPlay label="Listen" />
         </div>
      </div>

      {/* Input Display Area */}
      <div className="bg-white border-4 border-blue-200 rounded-2xl w-full max-w-md h-20 mb-6 flex items-center justify-center gap-1 shadow-inner overflow-hidden relative">
         {userInput.map((char, idx) => (
             <span key={idx} className="text-4xl font-bold text-blue-600 animate-in fade-in slide-in-from-bottom-2">
                 {char}
             </span>
         ))}
         {userInput.length === 0 && !isPenaltyActive && (
             <span className="text-gray-300 text-lg">Type letters below...</span>
         )}
         <span className="w-1 h-8 bg-blue-400 animate-pulse ml-1"></span>
      </div>

      {/* Controls Container */}
      <div className={`transition-opacity duration-300 ${isPenaltyActive ? 'opacity-20 pointer-events-none' : 'opacity-100'}`}>

          {/* Tone Bar */}
          <div className="flex gap-2 mb-4 justify-center">
             {['¯', '´', 'ˇ', '`'].map((symbol, idx) => (
                 <button
                    key={idx}
                    onClick={() => handleToneChange(idx)}
                    className="w-12 h-12 rounded-xl bg-orange-100 hover:bg-orange-200 border-b-4 border-orange-300 text-2xl font-bold text-orange-800 btn-press"
                 >
                    {symbol}
                 </button>
             ))}
             <button
                onClick={() => handleToneChange(4)} // Neutral tone
                className="w-12 h-12 rounded-xl bg-orange-50 hover:bg-orange-100 border-b-4 border-orange-200 text-sm font-bold text-orange-600 btn-press flex items-center justify-center"
             >
                None
             </button>
          </div>

          {/* Letter Keyboard */}
          <div className="grid grid-cols-6 gap-2 mb-6 max-w-md">
             {letterPool.map((char, idx) => (
                 <button
                    key={`${char}-${idx}`}
                    onClick={() => handleAddLetter(char)}
                    className="w-12 h-12 rounded-xl bg-blue-50 hover:bg-blue-100 border-b-4 border-blue-200 text-xl font-bold text-blue-700 btn-press"
                 >
                    {char}
                 </button>
             ))}
             <button
                onClick={handleBackspace}
                className="col-span-2 bg-red-100 hover:bg-red-200 border-b-4 border-red-300 rounded-xl font-bold text-red-600 btn-press flex items-center justify-center gap-1"
             >
                ⌫ Del
             </button>
          </div>

          {/* Submit Button */}
          <button
            onClick={checkAnswer}
            disabled={userInput.length === 0}
            className={`
                w-full max-w-md py-4 rounded-2xl font-bold text-xl text-white transition-all
                ${userInput.length === 0 
                    ? 'bg-gray-300 cursor-not-allowed' 
                    : 'bg-green-500 hover:bg-green-600 border-b-4 border-green-700 btn-press'}
            `}
          >
            Check Answer ✅
          </button>
      </div>

      {/* Penalty Overlay */}
      {isPenaltyActive && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
           <div className="bg-white rounded-[2rem] p-8 border-8 border-yellow-400 shadow-2xl flex flex-col items-center w-full max-w-sm animate-bounce-small">
              <div className="text-6xl mb-2">🙈</div>
              <h3 className="text-2xl font-bold text-gray-600 mb-2">Oops! Correct answer:</h3>

              <div className="text-6xl font-bold text-blue-600 mb-6 tracking-wider">
                  {currentItem.pinyin}
              </div>

              <div className="w-full bg-gray-200 rounded-full h-4 mb-4 overflow-hidden">
                  <div 
                    className="bg-red-500 h-full transition-all duration-1000 ease-linear"
                    style={{ width: `${(penaltyTime / 10) * 100}%` }}
                  ></div>
              </div>

              <p className="text-lg font-bold text-gray-500">
                  Try again in <span className="text-red-500 text-2xl">{penaltyTime}</span> seconds
              </p>

              {penaltyTime === 0 && (
                  <button 
                    onClick={() => {
                        setPenaltyTime(0);
                        setUserInput([]); // Clear input to restart
                    }}
                    className="mt-4 px-8 py-3 bg-blue-500 text-white font-bold rounded-xl border-b-4 border-blue-700 btn-press"
                  >
                      Try Again 🔄
                  </button>
              )}
           </div>
        </div>
      )}

      <div className="mt-6 text-gray-400 font-bold">
        {currentIndex + 1} / {data.length}
      </div>
    </div>
  );
};

export default PinyinPractice;

import React, { useState, useRef, useEffect } from 'react';
import { VocabularyItem, SubmissionRecord } from '../types';
import AudioPlayer from './AudioPlayer';
import { PLACEHOLDER_IMAGES } from '../constants';

interface Props {
  data: VocabularyItem[];
  onComplete: () => void;
  onRecord: (record: SubmissionRecord) => void;
}

const SpeakingPractice: React.FC<Props> = ({ data, onComplete, onRecord }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isRecording, setIsRecording] = useState(false);
  const [recordedBlob, setRecordedBlob] = useState<Blob | null>(null);
  const [audioUrl, setAudioUrl] = useState<string | null>(null);

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);

  const currentItem = data[currentIndex];

  // Cleanup object URL
  useEffect(() => {
    return () => {
      if (audioUrl) URL.revokeObjectURL(audioUrl);
    };
  }, [audioUrl]);

  const toggleRecording = async () => {
    if (isRecording) {
      stopRecording();
    } else {
      await startRecording();
    }
  };

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      chunksRef.current = [];

      mediaRecorder.ondataavailable = (e) => {
        if (e.data.size > 0) chunksRef.current.push(e.data);
      };

      mediaRecorder.onstop = () => {
        const blob = new Blob(chunksRef.current, { type: 'audio/webm' });
        setRecordedBlob(blob);
        const url = URL.createObjectURL(blob);
        setAudioUrl(url);
      };

      mediaRecorder.start();
      setIsRecording(true);
      // Clear previous recording
      setRecordedBlob(null);
      if (audioUrl) URL.revokeObjectURL(audioUrl);
      setAudioUrl(null);
    } catch (err) {
      console.error("Mic error", err);
      alert("Please allow microphone access!");
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      mediaRecorderRef.current.stream.getTracks().forEach(track => track.stop());
    }
  };

  const playRecording = () => {
    if (audioUrl) {
      new Audio(audioUrl).play();
    }
  };

  const handleNext = () => {
    // Determine the record for the current item
    const newRecord: SubmissionRecord | null = recordedBlob ? {
         type: 'speaking',
         itemId: currentItem.id,
         input: recordedBlob,
         score: 1, // Participation score
         feedback: "Recorded"
      } : null;

    // Report to parent
    if (newRecord) {
        onRecord(newRecord);
    }

    // Reset local state for next item
    setRecordedBlob(null);
    setAudioUrl(null);
    setIsRecording(false); // Ensure stopped

    if (currentIndex < data.length - 1) {
      setCurrentIndex(prev => prev + 1);
    } else {
      // Finished all items
      onComplete();
    }
  };

  return (
    <div className="flex flex-col items-center justify-center h-full">
      <h2 className="text-3xl font-bold text-gray-700 mb-6">🎤 Listen & Repeat</h2>

      <div className="bg-green-50 p-6 rounded-3xl border-4 border-green-200 mb-8 flex flex-col items-center gap-4 w-full max-w-md">
         <img 
          src={PLACEHOLDER_IMAGES[currentItem.imageKeyword]} 
          alt={currentItem.english}
          className="w-48 h-48 object-cover rounded-2xl border-2 border-white shadow-md mb-2"
        />
        <div className="text-6xl font-bold text-gray-800">{currentItem.chinese}</div>
        <div className="text-2xl text-blue-500 font-bold">{currentItem.pinyin}</div>
        <AudioPlayer text={currentItem.chinese} label="Hear Teacher" />
      </div>

      <div className="w-full max-w-md flex flex-col gap-4">

        {/* Controls */}
        <div className="flex gap-4">
            <button
                onClick={toggleRecording}
                className={`
                flex-1 py-4 rounded-2xl font-bold text-xl text-white shadow-lg transition-all
                ${isRecording 
                    ? 'bg-red-500 animate-pulse border-b-4 border-red-700' 
                    : 'bg-purple-500 hover:bg-purple-600 border-b-4 border-purple-700 btn-press'}
                `}
            >
                {isRecording ? '⏹️ Stop' : '🎙️ Record'}
            </button>

            {audioUrl && !isRecording && (
                <button
                    onClick={playRecording}
                    className="flex-1 py-4 rounded-2xl font-bold text-xl text-white bg-yellow-400 hover:bg-yellow-500 border-b-4 border-yellow-600 btn-press"
                >
                    ▶️ Play Back
                </button>
            )}
        </div>

        {/* Status Indicator */}
        <div className="h-8 flex items-center justify-center">
            {isRecording && <span className="text-red-500 font-bold animate-bounce">Recording...</span>}
            {!isRecording && recordedBlob && <span className="text-green-600 font-bold">Recorded! Ready to save.</span>}
        </div>

        {/* Navigation - Only allow next if recorded at least once */}
        {recordedBlob && !isRecording && (
          <button
            onClick={handleNext}
            className="w-full py-4 rounded-2xl font-bold text-xl text-white bg-blue-400 hover:bg-blue-500 border-b-4 border-blue-600 btn-press"
          >
            {currentIndex < data.length - 1 ? "Save & Next ➡️" : "Save & Finish 🏁"}
          </button>
        )}
      </div>

      <div className="mt-8 text-gray-400 font-bold">
        {currentIndex + 1} / {data.length}
      </div>
    </div>
  );
};

export default SpeakingPractice;

import React, { useState } from 'react';
import { VocabularyItem, SubmissionRecord } from '../types';
import { SOUNDS } from '../constants';

interface Props {
  data: VocabularyItem[];
  onComplete: () => void;
  onRecord: (record: SubmissionRecord) => void;
}

const Quiz: React.FC<Props> = ({ data, onComplete, onRecord }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [showResult, setShowResult] = useState<'correct' | 'wrong' | null>(null);

  const currentItem = data[currentIndex];

  // Generate options logic (inline for simplicity in this component)
  const generateOptions = (target: VocabularyItem, all: VocabularyItem[]) => {
    const others = all.filter(i => i.id !== target.id).sort(() => 0.5 - Math.random()).slice(0, 2);
    return [target, ...others].sort(() => 0.5 - Math.random());
  };

  const [currentOptions, setCurrentOptions] = useState<VocabularyItem[]>(generateOptions(currentItem, data));

  const handleSelect = (selectedId: string) => {
    if (showResult === 'correct') return; // prevent clicking after success

    if (selectedId === currentItem.id) {
      new Audio(SOUNDS.CORRECT).play();
      setShowResult('correct');

      // Submit record
      onRecord({
        type: 'quiz',
        itemId: currentItem.id,
        score: 1,
        input: 'Correct Match',
        feedback: 'Correct'
      });

      setTimeout(() => {
        if (currentIndex < data.length - 1) {
            const nextIdx = currentIndex + 1;
            setCurrentIndex(nextIdx);
            setCurrentOptions(generateOptions(data[nextIdx], data));
            setShowResult(null);
        } else {
            onComplete();
        }
      }, 1000);
    } else {
      new Audio(SOUNDS.WRONG).play();
      setShowResult('wrong');
    }
  };

  return (
    <div className="flex flex-col items-center justify-center h-full">
      <h2 className="text-3xl font-bold text-gray-700 mb-8">🧩 Match Meanings</h2>

      {/* Pinyin Cards Display */}
      <div className="flex flex-wrap gap-4 justify-center mb-10">
        {currentItem.pinyin.split(' ').map((syllable, idx) => (
            <div 
              key={`${currentItem.id}-${idx}`} 
              className="bg-white px-6 py-4 rounded-2xl shadow-md border-4 border-blue-100 transform -rotate-1 min-w-[100px] text-center"
            >
                <span className="text-5xl sm:text-6xl font-bold text-blue-600 font-sans tracking-wide">
                  {syllable}
                </span>
            </div>
        ))}
      </div>

      <div className="grid grid-cols-1 gap-4 w-full max-w-md">
        {currentOptions.map((opt) => (
          <button
            key={opt.id}
            onClick={() => handleSelect(opt.id)}
            className={`
              relative p-6 rounded-2xl border-b-4 font-bold text-2xl transition-all
              ${showResult === 'correct' && opt.id === currentItem.id 
                ? 'bg-green-100 border-green-500 text-green-800 scale-105' 
                : 'bg-white hover:bg-yellow-50 border-gray-200 text-gray-700 btn-press'}
              ${showResult === 'wrong' && opt.id !== currentItem.id ? 'opacity-50' : ''}
              ${showResult === 'wrong' && opt.id === currentItem.id ? 'ring-2 ring-green-400' : ''} 
            `}
          >
            {opt.english}

            {showResult === 'correct' && opt.id === currentItem.id && (
               <span className="absolute right-4 top-1/2 -translate-y-1/2 text-3xl">✅</span>
            )}
          </button>
        ))}
      </div>

       {showResult === 'wrong' && (
          <div className="mt-6 text-red-500 font-bold text-xl animate-bounce">Try again!</div>
       )}
    </div>
  );
};

export default Quiz;

import React, { useState, useRef, useEffect } from 'react';
import { DialogueGroup, SubmissionRecord } from '../types';
import AudioPlayer from './AudioPlayer';
import { SOUNDS } from '../constants';

interface Props {
  data: DialogueGroup[];
  onComplete: () => void;
  onRecord: (record: SubmissionRecord) => void;
}

const DialoguePractice: React.FC<Props> = ({ data, onComplete, onRecord }) => {
  const [currentGroupIdx, setCurrentGroupIdx] = useState(0);
  const [isRecording, setIsRecording] = useState(false);
  const [recordedBlob, setRecordedBlob] = useState<Blob | null>(null);
  const [audioUrl, setAudioUrl] = useState<string | null>(null);

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);

  const currentDialogue = data[currentGroupIdx];

  // Cleanup audio url
  useEffect(() => {
    return () => {
      if (audioUrl) URL.revokeObjectURL(audioUrl);
    };
  }, [audioUrl]);

  // Recording Logic
  const toggleRecording = async () => {
    if (isRecording) {
      stopRecording();
    } else {
      await startRecording();
    }
  };

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      chunksRef.current = [];

      mediaRecorder.ondataavailable = (e) => {
        if (e.data.size > 0) chunksRef.current.push(e.data);
      };

      mediaRecorder.onstop = () => {
        const blob = new Blob(chunksRef.current, { type: 'audio/webm' });
        setRecordedBlob(blob);
        const url = URL.createObjectURL(blob);
        setAudioUrl(url);
      };

      mediaRecorder.start();
      setIsRecording(true);
      setRecordedBlob(null);
      if (audioUrl) URL.revokeObjectURL(audioUrl);
      setAudioUrl(null);
    } catch (err) {
      console.error("Mic error", err);
      alert("Please allow microphone access!");
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      mediaRecorderRef.current.stream.getTracks().forEach(track => track.stop());
    }
  };

  const playRecording = () => {
    if (audioUrl) new Audio(audioUrl).play();
  };

  const handleNext = () => {
    // Save record if available
    if (recordedBlob) {
        // Find the B line to associate ID (using dialogue ID + index as mock ID)
        const studentLineIdx = currentDialogue.lines.findIndex(l => l.speaker === 'B');
        const itemId = `${currentDialogue.id}_line${studentLineIdx}`;

        onRecord({
            type: 'speaking',
            itemId: itemId,
            input: recordedBlob,
            score: 1,
            feedback: 'Dialogue Response'
        });
    }

    // Reset local state
    setRecordedBlob(null);
    setAudioUrl(null);
    setIsRecording(false);

    if (currentGroupIdx < data.length - 1) {
      setCurrentGroupIdx(prev => prev + 1);
    } else {
      onComplete();
    }
  };

  return (
    <div className="flex flex-col items-center h-full">
      <h2 className="text-3xl font-bold text-gray-700 mb-4">💬 Role Play</h2>
      <p className="text-gray-500 mb-6">Teacher reads A. You read & record B.</p>

      <div className="flex flex-col gap-6 w-full max-w-lg mb-8 overflow-y-auto pr-2">
        {currentDialogue.lines.map((line, idx) => (
          <div key={idx} className={`flex gap-4 ${line.speaker === 'B' ? 'flex-row-reverse' : ''}`}>
            {/* Avatar */}
            <div className={`
              w-14 h-14 rounded-full flex items-center justify-center text-white font-bold text-xl shadow-md shrink-0
              ${line.speaker === 'A' ? 'bg-blue-400' : 'bg-pink-400'}
            `}>
              {line.speaker === 'A' ? '👨‍🏫' : '🧑‍🎓'}
            </div>

            {/* Bubble */}
            <div className={`
              flex-1 p-5 rounded-3xl border-2 relative
              ${line.speaker === 'A' ? 'bg-blue-50 border-blue-100 rounded-tl-none' : 'bg-pink-50 border-pink-100 rounded-tr-none'}
            `}>
              <p className="text-2xl font-bold text-gray-800 mb-1">{line.chinese}</p>
              <p className="text-gray-600 mb-2 font-medium">{line.pinyin}</p>
              <p className="text-sm text-gray-400 italic mb-3">{line.english}</p>

              {line.speaker === 'A' && (
                 <div className="flex justify-start">
                    <AudioPlayer text={line.chinese} label="Listen" />
                 </div>
              )}

              {line.speaker === 'B' && (
                <div className="flex flex-col gap-2 mt-2 bg-white/50 p-2 rounded-xl">
                   <div className="flex gap-2">
                      <button
                        onClick={toggleRecording}
                        className={`
                            flex-1 py-2 rounded-xl font-bold text-sm text-white transition-all
                            ${isRecording 
                                ? 'bg-red-500 animate-pulse' 
                                : 'bg-pink-500 hover:bg-pink-600 btn-press'}
                        `}
                      >
                        {isRecording ? 'Stop' : '🎙️ Record'}
                      </button>
                      {audioUrl && !isRecording && (
                        <button
                            onClick={playRecording}
                            className="px-4 py-2 rounded-xl font-bold text-sm text-white bg-yellow-400 hover:bg-yellow-500 btn-press"
                        >
                            ▶️
                        </button>
                      )}
                   </div>
                   {recordedBlob && !isRecording && (
                       <div className="text-xs text-center text-green-600 font-bold">Recorded!</div>
                   )}
                </div>
              )}
            </div>
          </div>
        ))}
      </div>

      <div className="mt-auto w-full max-w-md">
         {/* Only enable Next if user has recorded something (if there is a B line) or just always allow for flexibility */}
         <button
            onClick={() => {
                new Audio(SOUNDS.SUCCESS).play();
                handleNext();
            }}
            disabled={currentDialogue.lines.some(l => l.speaker === 'B') && !recordedBlob}
            className={`
                w-full py-4 rounded-2xl font-bold text-xl text-white border-b-4 btn-press transition-all
                ${(currentDialogue.lines.some(l => l.speaker === 'B') && !recordedBlob)
                    ? 'bg-gray-300 border-gray-400 cursor-not-allowed'
                    : 'bg-orange-400 hover:bg-orange-500 border-orange-600'}
            `}
          >
            {currentGroupIdx < data.length - 1 ? "Next Dialogue ➡️" : "Finish! 🎉"}
          </button>
      </div>
    </div>
  );
};

export default DialoguePractice;

import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import PinyinPractice from './components/PinyinPractice';
import SpeakingPractice from './components/SpeakingPractice';
import Quiz from './components/Quiz';
import DialoguePractice from './components/DialoguePractice';
import TeacherPortal from './components/TeacherPortal';
import { ActivityType, SubmissionRecord, Lesson } from './types';
import { LESSONS, SOUNDS } from './constants';
import { saveHomeworkReport } from './services/reportService';

interface AIStudioWindow {
  aistudio?: {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  };
}

// Separate component to prevent input focus loss on re-renders
const PartialSubmitBar: React.FC<{
  studentName: string;
  setStudentName: (s: string) => void;
  submissionsCount: number;
  onSubmit: () => void;
  isSubmitting: boolean;
}> = ({ studentName, setStudentName, submissionsCount, onSubmit, isSubmitting }) => (
    <div className="mt-8 pt-6 border-t-2 border-dashed border-gray-300 w-full flex flex-col items-center gap-2">
            <h4 className="text-gray-400 font-bold text-sm uppercase tracking-widest">Submit Progress Independently</h4>
            <div className="flex gap-2 w-full max-w-md">
                <input 
                    value={studentName}
                    onChange={(e) => setStudentName(e.target.value)}
                    placeholder="Enter Name"
                    className="flex-1 bg-gray-50 border-2 border-gray-300 rounded-xl px-4 font-bold text-gray-700 h-12"
                />
                <button 
                    onClick={onSubmit}
                    disabled={isSubmitting || submissionsCount === 0}
                    className={`
                        px-6 rounded-xl font-bold text-white whitespace-nowrap h-12 flex items-center
                        ${submissionsCount > 0 
                            ? 'bg-yellow-400 hover:bg-yellow-500 text-yellow-900 border-b-4 border-yellow-600 btn-press' 
                            : 'bg-gray-300 text-gray-500 cursor-not-allowed'}
                    `}
                >
                    {isSubmitting ? 'Sending...' : `Submit (${submissionsCount})`}
                </button>
            </div>
            <p className="text-xs text-gray-400">You can submit items now or continue to other modules.</p>
        </div>
);

const App: React.FC = () => {
  // Main State
  const [userRole, setUserRole] = useState<'student' | 'teacher' | null>(null);
  const [activity, setActivity] = useState<ActivityType>(ActivityType.LESSON_SELECT);

  // Student State
  const [currentLessonId, setCurrentLessonId] = useState<number | null>(null);
  const [submissions, setSubmissions] = useState<SubmissionRecord[]>([]);
  const [completedLessons, setCompletedLessons] = useState<number[]>([]);
  const [nextActivity, setNextActivity] = useState<ActivityType>(ActivityType.MENU);

  // Submission State
  const [studentName, setStudentName] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [hasApiKey, setHasApiKey] = useState(false);

  useEffect(() => {
    const checkKey = async () => {
      const win = window as unknown as AIStudioWindow;
      if (win.aistudio) {
        const has = await win.aistudio.hasSelectedApiKey();
        setHasApiKey(has);
      } else {
        setHasApiKey(true);
      }
    };
    checkKey();
  }, []);

  const handleSelectKey = async () => {
    const win = window as unknown as AIStudioWindow;
    if (win.aistudio) {
      await win.aistudio.openSelectKey();
      setHasApiKey(true);
    }
  };

  const getActiveLesson = (): Lesson => {
    return LESSONS.find(l => l.id === currentLessonId) || LESSONS[0];
  };

  // --- Student Flow Handlers ---

  const handleLessonSelect = (id: number) => {
    setCurrentLessonId(id);
    setActivity(ActivityType.MENU);
  };

  const handleRecord = (record: SubmissionRecord) => {
    setSubmissions(prev => [...prev, record]);
  };

  const handleActivityComplete = () => {
    new Audio(SOUNDS.SUCCESS).play();

    // Determine next activity logic (standard flow)
    let next = ActivityType.MENU;
    switch (activity) {
        case ActivityType.PINYIN: next = ActivityType.SPEAKING; break;
        case ActivityType.SPEAKING: next = ActivityType.QUIZ; break;
        case ActivityType.QUIZ: next = ActivityType.DIALOGUE; break;
        case ActivityType.DIALOGUE: next = ActivityType.SUMMARY; break;
        default: next = ActivityType.MENU; break;
    }
    setNextActivity(next);

    // Show module success screen
    setActivity(ActivityType.MODULE_SUCCESS);
  };

  const handleContinue = () => {
      setActivity(nextActivity);
  };

  const handlePartialSubmit = async () => {
      if (submissions.length === 0) {
          alert("No new work to submit yet! Finish a module first.");
          return;
      }
      if (!studentName.trim()) {
          const name = prompt("Enter your name to submit:");
          if (name) setStudentName(name);
          else return;
      }

      setIsSubmitting(true);
      try {
          // Use current name or prompt again if somehow empty
          const nameToUse = studentName || "Anonymous";
          const success = await saveHomeworkReport(
              currentLessonId || 1,
              nameToUse,
              submissions
          );

          if (success) {
              alert(`✅ Successfully submitted ${submissions.length} items to teacher!`);
              setSubmissions([]); // Clear the queue after successful save
          } else {
              alert("Failed to save to database.");
          }
      } catch (e) {
          console.error(e);
          alert("Error submitting homework.");
      } finally {
          setIsSubmitting(false);
      }
  };

  // --- Navigation Handlers ---

  const handleSwitchRole = () => {
    if (userRole === 'student') {
        setUserRole('teacher');
        setActivity(ActivityType.TEACHER_PORTAL);
    } else {
        setUserRole('student');
        setActivity(ActivityType.LESSON_SELECT);
    }
  };

  const handleDirectNavigate = (type: ActivityType) => {
    if (type === ActivityType.TEACHER_PORTAL) {
        setUserRole('teacher');
        setActivity(type);
    } else {
        if (userRole !== 'student') setUserRole('student');

        // Ensure a lesson is selected if jumping to a specific activity
        if (type !== ActivityType.LESSON_SELECT && type !== ActivityType.MENU && currentLessonId === null) {
             setCurrentLessonId(1); // Default to lesson 1 if jumping blindly
        }
        setActivity(type);
    }
  };

  // --- Rendering ---

  if (!hasApiKey) {
    return (
        <Layout currentActivity={ActivityType.MENU} onHome={() => {}}>
            <div className="flex flex-col items-center justify-center h-full text-center">
                <h2 className="text-3xl font-bold text-gray-700 mb-6">Welcome to Panda Class! 🐼</h2>
                <button onClick={handleSelectKey} className="bg-blue-500 text-white font-bold py-4 px-8 rounded-full border-b-4 border-blue-700 btn-press">
                    🔑 Connect API Key
                </button>
            </div>
        </Layout>
    );
  }

  // Role Selection Screen (Initial)
  if (!userRole) {
      return (
          <Layout currentActivity={ActivityType.MENU} onHome={() => {}}>
             <div className="flex flex-col items-center justify-center h-full gap-8">
                 <h2 className="text-3xl font-bold text-gray-700">Who are you?</h2>
                 <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 w-full max-w-2xl">
                     <button 
                        onClick={() => { setUserRole('student'); setActivity(ActivityType.LESSON_SELECT); }}
                        className="bg-blue-100 hover:bg-blue-200 border-4 border-blue-300 p-8 rounded-3xl btn-press text-center group"
                     >
                         <div className="text-6xl mb-4 group-hover:scale-110 transition-transform">🧑‍🎓</div>
                         <div className="text-2xl font-bold text-blue-800">I am a Student</div>
                     </button>
                     <button 
                        onClick={() => { setUserRole('teacher'); setActivity(ActivityType.TEACHER_PORTAL); }}
                        className="bg-green-100 hover:bg-green-200 border-4 border-green-300 p-8 rounded-3xl btn-press text-center group"
                     >
                         <div className="text-6xl mb-4 group-hover:scale-110 transition-transform">👨‍🏫</div>
                         <div className="text-2xl font-bold text-green-800">I am a Teacher</div>
                     </button>
                 </div>
             </div>
          </Layout>
      );
  }

  // Teacher View
  if (userRole === 'teacher') {
      return (
        <Layout 
            currentActivity={ActivityType.TEACHER_PORTAL} 
            onHome={() => setActivity(ActivityType.LESSON_SELECT)}
            userRole={userRole}
            onSwitchRole={handleSwitchRole}
            onNavigate={handleDirectNavigate}
        >
            <TeacherPortal onBack={handleSwitchRole} />
        </Layout>
      );
  }

  // Student View Content Wrapper
  const renderStudentContent = () => {
    const activeLesson = getActiveLesson();

    switch (activity) {
      case ActivityType.LESSON_SELECT:
        return (
            <div className="w-full">
                <h2 className="text-3xl font-bold text-gray-700 mb-6 text-center">📚 Choose a Lesson</h2>
                <div className="grid grid-cols-1 gap-6">
                    {LESSONS.map(lesson => (
                        <button
                            key={lesson.id}
                            onClick={() => handleLessonSelect(lesson.id)}
                            className="bg-white hover:bg-blue-50 border-4 border-blue-200 rounded-3xl p-6 text-left shadow-sm btn-press flex justify-between items-center group"
                        >
                            <div>
                                <h3 className="text-2xl font-bold text-blue-600 group-hover:text-blue-700">{lesson.title}</h3>
                                <p className="text-gray-500 mt-2">{lesson.description}</p>
                            </div>
                            <span className="text-4xl opacity-20 group-hover:opacity-50">▶️</span>
                        </button>
                    ))}
                </div>
            </div>
        );

      case ActivityType.MENU:
        return (
          <div className="w-full">
            <h2 className="text-2xl font-bold text-gray-400 mb-6 text-center uppercase tracking-widest">{activeLesson.title}</h2>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 p-4">
                <MenuButton label="Step 1" title="✍️ 拼音书写" subtitle="Build Pinyin" color="bg-blue-400" onClick={() => setActivity(ActivityType.PINYIN)} />
                <MenuButton label="Step 2" title="🎤 口语跟读" subtitle="Listen & Repeat" color="bg-green-400" onClick={() => setActivity(ActivityType.SPEAKING)} />
                <MenuButton label="Step 3" title="🧩 听音辨意" subtitle="Match Meanings" color="bg-purple-400" onClick={() => setActivity(ActivityType.QUIZ)} />
                <MenuButton label="Step 4" title="💬 情景对话" subtitle="Role Play" color="bg-pink-400" onClick={() => setActivity(ActivityType.DIALOGUE)} />
            </div>
