                    {isSubmitting ? 'Sending...' : `Submit (${submissionsCount})`}
                </button>
            </div>
            <p className="text-xs text-gray-400">You can submit items now or continue to other modules.</p>
        </div>
);

const App: React.FC = () => {
  // Main State
  const [userRole, setUserRole] = useState<'student' | 'teacher' | null>(null);
  const [activity, setActivity] = useState<ActivityType>(ActivityType.LESSON_SELECT);

  // Student State
  const [currentLessonId, setCurrentLessonId] = useState<number | null>(null);
  const [submissions, setSubmissions] = useState<SubmissionRecord[]>([]);
  const [completedLessons, setCompletedLessons] = useState<number[]>([]);
  const [nextActivity, setNextActivity] = useState<ActivityType>(ActivityType.MENU);

  // Submission State
  const [studentName, setStudentName] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [hasApiKey, setHasApiKey] = useState(false);

  // Load saved name from local storage on mount
  useEffect(() => {
    const savedName = localStorage.getItem('panda_student_name');
    if (savedName) {
        setStudentName(savedName);
    }
  }, []);

  // Update saved name whenever it changes
  const handleNameChange = (name: string) => {
      setStudentName(name);
      localStorage.setItem('panda_student_name', name);
  };

  useEffect(() => {
    const checkKey = async () => {
      const win = window as unknown as AIStudioWindow;
      if (win.aistudio) {
        const has = await win.aistudio.hasSelectedApiKey();
        setHasApiKey(has);
      } else {
        setHasApiKey(true);
      }
    };
    checkKey();
  }, []);

  const handleSelectKey = async () => {
    const win = window as unknown as AIStudioWindow;
    if (win.aistudio) {
      await win.aistudio.openSelectKey();
      setHasApiKey(true);
    }
  };

  const getActiveLesson = (): Lesson => {
    return LESSONS.find(l => l.id === currentLessonId) || LESSONS[0];
  };

  // --- Student Flow Handlers ---

  const handleLessonSelect = (id: number) => {
    setCurrentLessonId(id);
    setActivity(ActivityType.MENU);
  };

  const handleRecord = (record: SubmissionRecord) => {
    setSubmissions(prev => [...prev, record]);
  };

  const handleActivityComplete = () => {
    new Audio(SOUNDS.SUCCESS).play();

    // Determine next activity logic (standard flow)
    let next = ActivityType.MENU;
    switch (activity) {
        case ActivityType.PINYIN: next = ActivityType.SPEAKING; break;
        case ActivityType.SPEAKING: next = ActivityType.QUIZ; break;
        case ActivityType.QUIZ: next = ActivityType.DIALOGUE; break;
        case ActivityType.DIALOGUE: next = ActivityType.SUMMARY; break;
        default: next = ActivityType.MENU; break;
    }
    setNextActivity(next);

    // Show module success screen
    setActivity(ActivityType.MODULE_SUCCESS);
  };

  const handleContinue = () => {
      setActivity(nextActivity);
  };

  const handlePartialSubmit = async () => {
      if (submissions.length === 0) {
          alert("No new work to submit yet! Finish a module first.");
          return;
      }
      if (!studentName.trim()) {
          const name = prompt("Enter your name to submit:");
          if (name) handleNameChange(name);
          else return;
      }

      setIsSubmitting(true);
      try {
          // Use current name or prompt again if somehow empty
          const nameToUse = studentName || "Anonymous";
          const success = await saveHomeworkReport(
              currentLessonId || 1,
              nameToUse,
              submissions
          );

          if (success) {
              alert(`✅ Successfully submitted ${submissions.length} items to teacher!`);
              setSubmissions([]); // Clear the queue after successful save
          } else {
              alert("Failed to save to database.");
          }
      } catch (e) {
          console.error(e);
          alert("Error submitting homework.");
      } finally {
          setIsSubmitting(false);
      }
  };

  // --- Navigation Handlers ---

  const handleSwitchRole = () => {
    if (userRole === 'student') {
        setUserRole('teacher');
        setActivity(ActivityType.TEACHER_PORTAL);
    } else {
        setUserRole('student');
        setActivity(ActivityType.LESSON_SELECT);
    }
  };

  const handleDirectNavigate = (type: ActivityType) => {
    if (type === ActivityType.TEACHER_PORTAL) {
        setUserRole('teacher');
        setActivity(type);
    } else {
        if (userRole !== 'student') setUserRole('student');

        // Ensure a lesson is selected if jumping to a specific activity
        if (type !== ActivityType.LESSON_SELECT && type !== ActivityType.MENU && currentLessonId === null) {
             setCurrentLessonId(1); // Default to lesson 1 if jumping blindly
        }
        setActivity(type);
    }
  };

  // --- Rendering ---

  if (!hasApiKey) {
    return (
        <Layout currentActivity={ActivityType.MENU} onHome={() => {}}>
            <div className="flex flex-col items-center justify-center h-full text-center">
                <h2 className="text-3xl font-bold text-gray-700 mb-6">Welcome to Panda Class! 🐼</h2>
                <button onClick={handleSelectKey} className="bg-blue-500 text-white font-bold py-4 px-8 rounded-full border-b-4 border-blue-700 btn-press">
                    🔑 Connect API Key
                </button>
            </div>
        </Layout>
    );
  }

  // Role Selection Screen (Initial)
  if (!userRole) {
      return (
          <Layout currentActivity={ActivityType.MENU} onHome={() => {}}>
             <div className="flex flex-col items-center justify-center h-full gap-8">
                 <h2 className="text-3xl font-bold text-gray-700">Who are you?</h2>
                 <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 w-full max-w-2xl">
                     <button 
                        onClick={() => { setUserRole('student'); setActivity(ActivityType.LESSON_SELECT); }}
                        className="bg-blue-100 hover:bg-blue-200 border-4 border-blue-300 p-8 rounded-3xl btn-press text-center group"
                     >
                         <div className="text-6xl mb-4 group-hover:scale-110 transition-transform">🧑‍🎓</div>
                         <div className="text-2xl font-bold text-blue-800">I am a Student</div>
                     </button>
                     <button 
                        onClick={() => { setUserRole('teacher'); setActivity(ActivityType.TEACHER_PORTAL); }}
                        className="bg-green-100 hover:bg-green-200 border-4 border-green-300 p-8 rounded-3xl btn-press text-center group"
                     >
                         <div className="text-6xl mb-4 group-hover:scale-110 transition-transform">👨‍🏫</div>
                         <div className="text-2xl font-bold text-green-800">I am a Teacher</div>
                     </button>
                 </div>
             </div>
          </Layout>
      );
  }

  // Teacher View
  if (userRole === 'teacher') {
      return (
        <Layout 
            currentActivity={ActivityType.TEACHER_PORTAL} 
            onHome={() => setActivity(ActivityType.LESSON_SELECT)}
            userRole={userRole}
            onSwitchRole={handleSwitchRole}
            onNavigate={handleDirectNavigate}
        >
            <TeacherPortal onBack={handleSwitchRole} />
        </Layout>
      );
  }

  // Student View Content Wrapper
  const renderStudentContent = () => {
    const activeLesson = getActiveLesson();

    switch (activity) {
      case ActivityType.LESSON_SELECT:
        return (
            <div className="w-full">
                <h2 className="text-3xl font-bold text-gray-700 mb-6 text-center">📚 Choose a Lesson</h2>
                <div className="grid grid-cols-1 gap-6">
                    {LESSONS.map(lesson => (
                        <button
                            key={lesson.id}
                            onClick={() => handleLessonSelect(lesson.id)}
                            className="bg-white hover:bg-blue-50 border-4 border-blue-200 rounded-3xl p-6 text-left shadow-sm btn-press flex justify-between items-center group"
                        >
                            <div>
                                <h3 className="text-2xl font-bold text-blue-600 group-hover:text-blue-700">{lesson.title}</h3>
                                <p className="text-gray-500 mt-2">{lesson.description}</p>
                            </div>
                            <span className="text-4xl opacity-20 group-hover:opacity-50">▶️</span>
                        </button>
                    ))}
                </div>
            </div>
        );

      case ActivityType.MENU:
        return (
          <div className="w-full">
            <h2 className="text-2xl font-bold text-gray-400 mb-6 text-center uppercase tracking-widest">{activeLesson.title}</h2>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 p-4">
                <MenuButton label="Step 1" title="✍️ 拼音书写" subtitle="Build Pinyin" color="bg-blue-400" onClick={() => setActivity(ActivityType.PINYIN)} />
                <MenuButton label="Step 2" title="🎤 口语跟读" subtitle="Listen & Repeat" color="bg-green-400" onClick={() => setActivity(ActivityType.SPEAKING)} />
                <MenuButton label="Step 3" title="🧩 听音辨意" subtitle="Match Meanings" color="bg-purple-400" onClick={() => setActivity(ActivityType.QUIZ)} />
                <MenuButton label="Step 4" title="💬 情景对话" subtitle="Role Play" color="bg-pink-400" onClick={() => setActivity(ActivityType.DIALOGUE)} />
            </div>
          </div>
        );

      case ActivityType.MODULE_SUCCESS:
        return (
          <div className="flex flex-col items-center justify-center h-full text-center w-full">
             <div className="text-6xl mb-4">🌟</div>
             <h2 className="text-3xl font-bold text-blue-600 mb-4">Good Job!</h2>

             <div className="flex flex-col gap-4 w-full max-w-sm">
                <button 
                    onClick={handleContinue}
                    className="w-full py-4 rounded-2xl font-bold text-xl text-white bg-blue-500 hover:bg-blue-600 border-b-4 border-blue-700 btn-press"
                >
                    {nextActivity === ActivityType.SUMMARY ? 'Finish Lesson 🏁' : 'Next Activity ➡️'}
                </button>
                <PartialSubmitBar 
                    studentName={studentName}
                    setStudentName={handleNameChange}
                    submissionsCount={submissions.length}
                    isSubmitting={isSubmitting}
                    onSubmit={handlePartialSubmit}
                />
             </div>
          </div>
        );

      // For all practice modes, append the PartialSubmitBar below
      // Now passing onRecord to all components to allow incremental state updates
      case ActivityType.PINYIN:
        return (
            <>
                <PinyinPractice data={activeLesson.vocabulary} onComplete={handleActivityComplete} onRecord={handleRecord} />
                <PartialSubmitBar 
                    studentName={studentName}
                    setStudentName={handleNameChange}
                    submissionsCount={submissions.length}
                    isSubmitting={isSubmitting}
                    onSubmit={handlePartialSubmit}
                />
            </>
        );
      case ActivityType.SPEAKING:
        return (
            <>
                <SpeakingPractice data={activeLesson.vocabulary} onComplete={handleActivityComplete} onRecord={handleRecord} />
                <PartialSubmitBar 
                    studentName={studentName}
                    setStudentName={handleNameChange}
                    submissionsCount={submissions.length}
                    isSubmitting={isSubmitting}
                    onSubmit={handlePartialSubmit}
                />
            </>
        );
      case ActivityType.QUIZ:
        return (
            <>
                <Quiz data={activeLesson.vocabulary} onComplete={handleActivityComplete} onRecord={handleRecord} />
                <PartialSubmitBar 
                    studentName={studentName}
                    setStudentName={handleNameChange}
                    submissionsCount={submissions.length}
                    isSubmitting={isSubmitting}
                    onSubmit={handlePartialSubmit}
                />
            </>
        );
      case ActivityType.DIALOGUE:
        return (
            <>
                <DialoguePractice data={activeLesson.dialogues} onComplete={handleActivityComplete} onRecord={handleRecord} />
                <PartialSubmitBar 
                    studentName={studentName}
                    setStudentName={handleNameChange}
                    submissionsCount={submissions.length}
                    isSubmitting={isSubmitting}
                    onSubmit={handlePartialSubmit}
                />
            </>
        );

      case ActivityType.SUMMARY:
          return (
             <div className="flex flex-col items-center justify-center h-full text-center w-full">
                 <div className="text-6xl mb-4">🎉</div>
                 <h2 className="text-3xl font-bold text-blue-600 mb-6">Lesson Complete!</h2>
                 <PartialSubmitBar 
                    studentName={studentName}
                    setStudentName={handleNameChange}
                    submissionsCount={submissions.length}
                    isSubmitting={isSubmitting}
                    onSubmit={handlePartialSubmit}
                />
             </div>
          );

      default:
        return null;
    }
  };

  return (
    <Layout 
        currentActivity={activity} 
        onHome={() => setActivity(ActivityType.LESSON_SELECT)}
        userRole={userRole}
        onSwitchRole={handleSwitchRole}
        onNavigate={handleDirectNavigate}
    >
      {renderStudentContent()}
    </Layout>
  );
};

const MenuButton: React.FC<{label: string; title: string; subtitle: string; color: string; onClick: () => void}> = ({ label, title, subtitle, color, onClick }) => (
  <button 
    onClick={onClick}
    className={`${color} hover:brightness-110 text-white p-6 rounded-[2rem] text-left border-b-8 border-black/20 btn-press flex flex-col justify-between h-40 sm:h-48`}
  >
    <div>
        <span className="text-xs sm:text-sm font-bold opacity-80 uppercase tracking-widest mb-1 block">{label}</span>
        <span className="text-2xl sm:text-3xl font-bold block mb-2">{title}</span>
    </div>
    <span className="text-md sm:text-lg opacity-90">{subtitle}</span>
  </button>
);

export default App;

import React, { useState, useEffect } from 'react';
import { SavedReport, Lesson, SubmissionRecord } from '../types';
import { getAllHomeworkReports, deleteReport, clearAllReports } from '../services/reportService';
import { LESSONS } from '../constants';

interface Props {
  onBack: () => void;
}

interface SubmissionItemProps {
  sub: SubmissionRecord;
  lesson: Lesson;
}

// Helper component to render specific submission items
const SubmissionItem: React.FC<SubmissionItemProps> = ({ sub, lesson }) => {
  const vocab = lesson.vocabulary.find(v => v.id === sub.itemId);
  // Ensure we check if dialogues exist, though Lesson interface enforces it
  const dialogueItem = lesson.dialogues?.find(d => sub.itemId.startsWith(d.id));

  // 1. Pinyin Writing
  if (sub.type === 'writing') {
      // Use score to determine if it was correct on first try, or compare input
      const isCorrect = sub.score > 0;
      return (
          <div className={`bg-white border-l-4 ${isCorrect ? 'border-blue-400' : 'border-red-400'} p-4 rounded-r-xl shadow-sm mb-3`}>
              <div className="flex justify-between items-start">
                  <div>
                      <span className="text-xs font-bold text-blue-500 uppercase tracking-wider">✍️ Pinyin Spelling</span>
                      <div className="font-bold text-gray-700 text-lg mt-1">{vocab?.chinese} ({vocab?.english})</div>
                  </div>
                  <div className="text-2xl">{isCorrect ? '✅' : '❌'}</div>
              </div>
              <div className="mt-2 flex gap-4 text-sm">
                  <div>
                      <span className="text-gray-400 block">Student Wrote:</span>
                      <span className={`font-mono font-bold text-lg ${isCorrect ? 'text-green-600' : 'text-red-500'}`}>
                          {typeof sub.input === 'string' ? sub.input : 'Media'}
                      </span>
                  </div>
                  {!isCorrect && (
                      <div>
                          <span className="text-gray-400 block">Correct Answer:</span>
                          <span className="font-mono font-bold text-gray-600 text-lg">{vocab?.pinyin}</span>
                      </div>
                  )}
              </div>
          </div>
      );
  }

  // 2. Speaking / Dialogue (Audio)
  if (sub.type === 'speaking' || sub.type === 'dialogue') {
      const audioUrl = sub.input instanceof Blob ? URL.createObjectURL(sub.input) : '';
      const title = sub.type === 'dialogue' || dialogueItem 
          ? '💬 Dialogue Roleplay' 
          : `🎤 Speaking: ${vocab?.chinese || 'Unknown'}`;

      return (
          <div className="bg-white border-l-4 border-green-400 p-4 rounded-r-xl shadow-sm mb-3">
              <div className="flex justify-between items-center mb-2">
                  <span className="text-xs font-bold text-green-600 uppercase tracking-wider">{title}</span>
                  <span className="text-xs bg-green-100 text-green-800 px-2 py-1 rounded">Audio</span>
              </div>
              {vocab && <div className="text-gray-500 text-sm mb-2">Prompt: {vocab.pinyin}</div>}

              {audioUrl ? (
                  <audio controls src={audioUrl} className="w-full h-10" />
              ) : (
                  <div className="text-gray-400 text-xs italic">No audio content</div>
              )}
          </div>
      );
  }

  // 3. Quiz
  if (sub.type === 'quiz') {
      const isCorrect = sub.score > 0;
      return (
            <div className={`bg-white border-l-4 ${isCorrect ? 'border-purple-400' : 'border-red-400'} p-4 rounded-r-xl shadow-sm mb-3 flex justify-between items-center`}>
                <div>
                  <span className="text-xs font-bold text-purple-500 uppercase tracking-wider">🧩 Quiz Match</span>
                  {/* FIX: Used &rarr; instead of -> to avoid JSX syntax error with > character */}
                  <div className="font-bold text-gray-700">{vocab?.chinese} &rarr; {vocab?.english}</div>
                </div>
                <div className="text-xl">{isCorrect ? '✅ Correct' : '❌ Wrong First Try'}</div>
            </div>
      );
  }

  return null;
};

const TeacherPortal: React.FC<Props> = ({ onBack }) => {
  const [reports, setReports] = useState<SavedReport[]>([]);
  const [selectedReport, setSelectedReport] = useState<SavedReport | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadReports();
  }, []);

  const loadReports = async () => {
    setLoading(true);
    const data = await getAllHomeworkReports();
    setReports(data);
    setLoading(false);
  };

  const handleDelete = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (confirm("Delete this homework?")) {
      await deleteReport(id);
      loadReports();
      if (selectedReport?.id === id) setSelectedReport(null);
    }
  };

  const handleClearAll = async () => {
      if (confirm("Delete ALL homework history? This cannot be undone.")) {
          await clearAllReports();
          loadReports();
          setSelectedReport(null);
      }
  };

  // --- Render Detail View ---
  if (selectedReport) {
      const lesson = LESSONS.find(l => l.id === selectedReport.lessonId) || LESSONS[0];

      return (
          <div className="h-full flex flex-col">
              <div className="flex items-center gap-4 mb-4 pb-4 border-b">
                  <button onClick={() => setSelectedReport(null)} className="text-2xl hover:scale-110 transition-transform">⬅️</button>
                  <div>
                      <h2 className="text-2xl font-bold text-gray-800">{selectedReport.studentName}'s Homework</h2>
                      <p className="text-gray-500 text-sm">{lesson.title} • {new Date(selectedReport.timestamp).toLocaleString()}</p>
                  </div>
              </div>

              <div className="flex-1 overflow-y-auto pr-2">
                  <div className="flex gap-4 mb-6">
                      <div className="flex-1 bg-yellow-50 border border-yellow-200 p-4 rounded-xl text-center">
                          <div className="text-3xl font-bold text-yellow-600">{selectedReport.totalScore}</div>
                          <div className="text-xs text-yellow-800 uppercase font-bold">Total Score</div>
                      </div>
                      <div className="flex-1 bg-blue-50 border border-blue-200 p-4 rounded-xl text-center">
                          <div className="text-3xl font-bold text-blue-600">{selectedReport.submissionsCount}</div>
                          <div className="text-xs text-blue-800 uppercase font-bold">Items Completed</div>
                      </div>
                  </div>

                  <h3 className="text-gray-400 font-bold uppercase tracking-widest text-sm mb-4">Submission Details</h3>

                  {selectedReport.submissions.map((sub, idx) => (
                      <SubmissionItem key={idx} sub={sub} lesson={lesson} />
                  ))}
              </div>
          </div>
      );
  }

  // --- Render List View ---
  return (
    <div className="w-full h-full flex flex-col">
       <div className="flex justify-between items-center mb-6 pb-4 border-b">
         <h2 className="text-3xl font-bold text-gray-800">🍎 Teacher Portal</h2>
         <button onClick={onBack} className="text-gray-500 hover:text-gray-700 font-bold">Exit</button>
       </div>

       <div className="flex-1 flex flex-col">
           <div className="flex justify-between items-end mb-4">
               <h3 className="text-xl font-bold text-blue-800">Inbox ({reports.length})</h3>
               {reports.length > 0 && (
                   <button onClick={handleClearAll} className="text-xs text-red-400 hover:text-red-600 underline">Clear All History</button>
               )}
           </div>

           <div className="flex-1 overflow-y-auto space-y-3 pr-2">
               {loading ? (
                   <div className="text-center py-10 text-gray-400">Loading records...</div>
               ) : reports.length === 0 ? (
                   <div className="flex flex-col items-center justify-center h-64 bg-gray-50 rounded-3xl border-4 border-dashed border-gray-200">
                       <span className="text-5xl mb-4">📭</span>
                       <p className="text-gray-400 font-bold">No homework submitted yet.</p>
                   </div>
               ) : (
                   reports.map((report) => {
                       const lesson = LESSONS.find(l => l.id === report.lessonId);
                       return (
                           <div 
                             key={report.id}
                             onClick={() => setSelectedReport(report)}
                             className="bg-white border-2 border-gray-100 p-4 rounded-xl hover:border-blue-300 hover:shadow-md transition-all cursor-pointer group"
                           >
                               <div className="flex justify-between items-center">
                                   <div className="flex items-center gap-4">
                                       <div className="w-12 h-12 rounded-full bg-blue-100 text-2xl flex items-center justify-center">🧑‍🎓</div>
                                       <div>
                                           <div className="font-bold text-lg text-gray-800 group-hover:text-blue-600 transition-colors">
                                               {report.studentName}
                                           </div>
                                           <div className="text-sm text-gray-500">
                                               {lesson?.title || 'Unknown Lesson'}
                                           </div>
                                       </div>
                                   </div>
                                   <div className="flex flex-col items-end gap-1">
                                       <span className="font-bold text-yellow-600 bg-yellow-100 px-3 py-1 rounded-lg text-sm">
                                           {report.totalScore} pts
                                       </span>
                                       <span className="text-xs text-gray-400">
                                           {new Date(report.timestamp).toLocaleDateString()}
                                       </span>
                                   </div>
                               </div>
                               <div className="mt-3 flex gap-2 justify-end opacity-0 group-hover:opacity-100 transition-opacity">
                                    <button 
                                        className="text-xs text-red-400 hover:text-red-600 px-2 py-1"
                                        onClick={(e) => handleDelete(e, report.id)}
                                    >
                                        Delete
                                    </button>
                               </div>
                           </div>
                       );
                   })
               )}
           </div>
       </div>
    </div>
  );
};

export default TeacherPortal;

