import { SavedReport, SubmissionRecord } from '../types';
import { blobToBase64 } from './geminiService';

// --- IndexedDB Configuration ---
const DB_NAME = 'PandaClassDB';
const DB_VERSION = 2; // Incremented version
const STORE_REPORTS = 'homework_reports';

const openDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;
      if (!db.objectStoreNames.contains(STORE_REPORTS)) {
        db.createObjectStore(STORE_REPORTS, { keyPath: 'id' });
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
};

/**
 * Save a full student report including Audio Blobs to IndexedDB
 */
export const saveHomeworkReport = async (
  lessonId: number,
  studentName: string,
  submissions: SubmissionRecord[]
): Promise<SavedReport | null> => {
  try {
    const db = await openDB();

    // Calculate score
    const totalScore = submissions.reduce((acc, curr) => acc + (curr.score * 10), 0);

    const report: SavedReport = {
      id: crypto.randomUUID(),
      lessonId,
      studentName,
      timestamp: Date.now(),
      submissionsCount: submissions.length,
      totalScore,
      submissions: submissions // This array contains Blobs, which IndexedDB handles natively
    };

    await new Promise((resolve, reject) => {
      const tx = db.transaction(STORE_REPORTS, 'readwrite');
      const store = tx.objectStore(STORE_REPORTS);
      const req = store.add(report);

      req.onsuccess = () => resolve(true);
      req.onerror = () => reject(req.error);
    });

    return report;
  } catch (e) {
    console.error("Save failed", e);
    return null;
  }
};

/**
 * Get all homework summaries for the list
 */
export const getAllHomeworkReports = async (): Promise<SavedReport[]> => {
  try {
    const db = await openDB();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(STORE_REPORTS, 'readonly');
      const store = tx.objectStore(STORE_REPORTS);
      const req = store.getAll();

      req.onsuccess = () => {
        // Sort by newest first
        const results = req.result as SavedReport[];
        results.sort((a, b) => b.timestamp - a.timestamp);
        resolve(results);
      };
      req.onerror = () => reject(req.error);
    });
  } catch (e) {
    return [];
  }
};

/**
 * Delete a report
 */
export const deleteReport = async (id: string): Promise<void> => {
  const db = await openDB();
  const tx = db.transaction(STORE_REPORTS, 'readwrite');
  tx.objectStore(STORE_REPORTS).delete(id);
};

export const clearAllReports = async (): Promise<void> => {
    const db = await openDB();
    const tx = db.transaction(STORE_REPORTS, 'readwrite');
    tx.objectStore(STORE_REPORTS).clear();
};

// --- IMPORT / EXPORT UTILITIES ---

// Helper: Convert Base64 back to Blob
const base64ToBlob = (base64: string, mimeType: string): Blob => {
  const byteCharacters = atob(base64);
  const byteArrays = [];

  for (let offset = 0; offset < byteCharacters.length; offset += 512) {
    const slice = byteCharacters.slice(offset, offset + 512);
    const byteNumbers = new Array(slice.length);
    for (let i = 0; i < slice.length; i++) {
      byteNumbers[i] = slice.charCodeAt(i);
    }
    const byteArray = new Uint8Array(byteNumbers);
    byteArrays.push(byteArray);
  }

  return new Blob(byteArrays, { type: mimeType });
};

// Helper to prepare report for transport (convert Blobs to Base64)
const prepareReportForTransport = async (report: SavedReport) => {
    const serializableSubmissions = await Promise.all(report.submissions.map(async (sub) => {
        if (sub.input instanceof Blob) {
          const base64 = await blobToBase64(sub.input);
          return {
            ...sub,
            input: {
              type: 'blob',
              mimeType: sub.input.type,
              data: base64
            }
          };
        }
        return sub;
      }));

      return {
        ...report,
        submissions: serializableSubmissions
      };
};

// Helper to parse report from transport (Base64 back to Blobs)
const parseReportFromTransport = (json: any): SavedReport => {
    const submissions = json.submissions.map((sub: any) => {
        if (sub.input && typeof sub.input === 'object' && sub.input.type === 'blob') {
          return {
            ...sub,
            input: base64ToBlob(sub.input.data, sub.input.mimeType)
          };
        }
        return sub;
     });

     return {
       ...json,
       submissions
     };
};

export const exportReportToJSON = async (report: SavedReport) => {
  const exportData = await prepareReportForTransport(report);
  const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(exportData));
  const downloadAnchorNode = document.createElement('a');
  downloadAnchorNode.setAttribute("href", dataStr);
  downloadAnchorNode.setAttribute("download", `panda_homework_${report.studentName}_${Date.now()}.json`);
  document.body.appendChild(downloadAnchorNode);
  downloadAnchorNode.click();
  downloadAnchorNode.remove();
};

// --- CLOUD UPLOAD / DOWNLOAD (Ephemeral) ---

/**
 * Uploads report to a temporary file host (file.io) and returns the KEY.
 * The file is automatically deleted after 1 download or 14 days.
 */
export const uploadReportToCloud = async (report: SavedReport): Promise<string | null> => {
    try {
        const exportData = await prepareReportForTransport(report);
        const jsonString = JSON.stringify(exportData);
        // Robustness: Use Blob instead of File to avoid browser compatibility quirks with fetch
        const blob = new Blob([jsonString], { type: 'application/json' });

        const formData = new FormData();
        formData.append('file', blob, 'homework.json');

        // Pass config params in URL to be safer against FormData parsing issues on some servers
        // Expires in 2 weeks
        const response = await fetch('https://file.io/?expires=2w', {
            method: 'POST',
            body: formData,
            mode: 'cors'
        });

        if (!response.ok) {
            throw new Error(`Upload failed with status: ${response.status}`);
        }

        const result = await response.json();
        if (result.success && result.key) {
            return result.key;
        }
        return null;
    } catch (e) {
        console.error("Cloud upload error", e);
        return null;
    }
};

/**
 * Downloads report from cloud using the KEY.
 */
export const downloadReportFromCloud = async (key: string): Promise<boolean> => {
    try {
        const response = await fetch(`https://file.io/${key}`);
        if (!response.ok) return false;

        // Validation: Ensure we actually got JSON back, not an HTML error page
        const contentType = response.headers.get("content-type");
        if (!contentType || !contentType.includes("application/json")) {
            console.warn("Received non-JSON response");
            // Attempt to parse anyway just in case headers are wrong
        }

        const json = await response.json();

        // Basic check to see if it looks like our report
        if (!json.id || !json.submissions) {
            return false;
        }

        const report = parseReportFromTransport(json);

        // Save to DB
        const db = await openDB();
        const tx = db.transaction(STORE_REPORTS, 'readwrite');
        const store = tx.objectStore(STORE_REPORTS);
        store.put(report);

        return true;
    } catch (e) {
        console.error("Cloud download error", e);
        return false;
    }
};

export const importReportFromJSON = async (file: File): Promise<boolean> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        const report = parseReportFromTransport(json);

        // Save to DB
        const db = await openDB();
        const tx = db.transaction(STORE_REPORTS, 'readwrite');
        const store = tx.objectStore(STORE_REPORTS);
        store.put(report); 

        resolve(true);
      } catch (e) {
        console.error("Import failed", e);
        resolve(false);
      }
    };
    reader.readAsText(file);
  });
};

