    if (type === ActivityType.TEACHER_PORTAL) {
        setUserRole('teacher');
        setActivity(type);
    } else {
        if (userRole !== 'student') setUserRole('student');
        if (type !== ActivityType.LESSON_SELECT && type !== ActivityType.MENU && currentLessonId === null) {
             setCurrentLessonId(1);
        }
        setActivity(type);
    }
  };

  // --- Rendering ---

  // 1. UPLOAD ERROR SCREEN (Fallback)
  if (uploadError) {
      return (
        <Layout currentActivity={ActivityType.MENU} onHome={() => {}}>
           <div className="flex flex-col items-center justify-center min-h-[50vh] gap-6 text-center w-full">
              <div className="text-8xl">📡❌</div>
              <div>
                  <h2 className="text-3xl font-bold text-gray-800 mb-2">Cloud Connection Failed</h2>
                  <p className="text-gray-500 max-w-md mx-auto">
